@final
def setitem(self, indexer, value):
    orig_indexer = indexer
    orig_value = value
    indexer = self._unwrap_setitem_indexer(indexer)
    value = self._maybe_squeeze_arg(value)
    values = self.values
    if values.ndim == 2:
        if not isinstance(indexer, tuple):
            indexer = (indexer, slice(None))
        if len(indexer) == 2:
            indexer = indexer[::-1]
        if isinstance(value, np.ndarray) and value.ndim == 2:
            value = value.T
    check_setitem_lengths(indexer, value, values)
    try:
        values[indexer] = value
    except (ValueError, TypeError):
        if isinstance(self.dtype, IntervalDtype):
            nb = self.coerce_to_target_dtype(orig_value, raise_on_upcast=True)
            return nb.setitem(orig_indexer, orig_value)
        elif isinstance(self, NDArrayBackedExtensionBlock):
            nb = self.coerce_to_target_dtype(orig_value, raise_on_upcast=True)
            return nb.setitem(orig_indexer, orig_value)
        else:
            raise
    else:
        return self

def generate_daily_offset_range(start: Timestamp | None, end: Timestamp | None, periods: int | None, freq: BaseOffset, unit: TimeUnit='ns') -> npt.NDArray[np.int64]:
    abs_n = freq.n
    trim_to = None
    trim_from_end = False
    if periods is not None:
        needed_on_offset = (periods - 1) * abs_n + 1
        buffer_days = needed_on_offset * 7 + 6
        if end is None:
            end = (start + Timedelta(days=buffer_days)).as_unit(unit)
        else:
            trim_from_end = True
            start = (end - Timedelta(days=buffer_days)).as_unit(unit)
        trim_to = periods
    i8values = generate_regular_range(start, end, None, Day(), unit=unit)
    dt64 = i8values.view(f'datetime64[{unit}]')
    i8values = i8values[freq._get_daily_offset_mask(dt64)]
    if abs_n > 1:
        if trim_from_end:
            i8values = i8values[::-1][::abs_n][::-1]
        else:
            i8values = i8values[::abs_n]
    if trim_to is not None:
        if trim_from_end:
            i8values = i8values[-trim_to:]
        else:
            i8values = i8values[:trim_to]
    return i8values

