    classes = np.unique(labels_true)
    clusters = np.unique(labels_pred)
    if classes.shape[0] == clusters.shape[0] == 1 or classes.shape[0] == clusters.shape[0] == 0:
        return 1.0
    elif classes.shape[0] == 1 or clusters.shape[0] == 1:
        return 0.0
    contingency = contingency_matrix(labels_true, labels_pred, sparse=True)
    mi = mutual_info_score(labels_true, labels_pred, contingency=contingency)
    emi = expected_mutual_information(contingency, n_samples)
    h_true, h_pred = (_entropy(labels_true), _entropy(labels_pred))
    normalizer = _generalized_average(h_true, h_pred, average_method)
    denominator = normalizer - emi
    if denominator < 0:
        denominator = min(denominator, -np.finfo('float64').eps)
    else:
        denominator = max(denominator, np.finfo('float64').eps)
    numerator = mi - emi
    if numerator < 0:
        numerator = min(numerator, -np.finfo('float64').eps)
    else:
        numerator = max(numerator, np.finfo('float64').eps)
    return float(numerator / denominator)

def _encode(item, *, uniques, check_unknown=True):
    xp, _ = get_namespace(item, uniques)
    if not xp.isdtype(item.dtype, 'numeric'):
        try:
            return _map_to_integer(item, uniques)
        except KeyError as e:
            raise ValueError(f'y contains previously unseen labels: {e}')
    else:
        if check_unknown:
            diff = _check_unknown(item, uniques)
            if diff:
                raise ValueError(f'y contains previously unseen labels: {diff}')
        return xp.searchsorted(uniques, item)

def __setitem__(self, key, value) -> None:
    if self._readonly:
        raise ValueError('Cannot modify read-only array')
    if isinstance(key, tuple) and len(key) == 1:
        key = key[0]
    key = check_array_indexer(self, key)
    value = self._validate_setitem_value(value)
    if com.is_null_slice(key):
        if isinstance(value, (pa.Array, pa.ChunkedArray)) and value.type == self._pa_array.type and (len(value) == len(self)):
            data = value
        else:
            data = self._if_else(True, value, self._pa_array)
    elif is_integer(key):
        key = cast('int', key)
        n = len(self)
        if key < 0:
            key += n
        if not 0 <= key < n:
            raise IndexError(f'index {key} is out of bounds for axis 0 with size {n}')
        if isinstance(value, pa.Scalar):
            value = value.as_py()
        elif is_list_like(value):
            raise ValueError('Length of indexer and values mismatch')
        chunks = [*self._pa_array[:key].chunks, pa.array([value], type=self._pa_array.type, from_pandas=is_nan_na()), *self._pa_array[key + 1:].chunks]
        data = pa.chunked_array(chunks).combine_chunks()
    elif is_bool_dtype(key):
        key = np.asarray(key, dtype=np.bool_)
        data = self._replace_with_mask(self._pa_array, key, value)
    elif is_scalar(value) or isinstance(value, pa.Scalar):
        mask = np.zeros(len(self), dtype=np.bool_)
        mask[key] = True
        data = self._if_else(mask, value, self._pa_array)
    else:
        indices = np.arange(len(self))[key]
        if len(indices) != len(value):
            raise ValueError('Length of indexer and values mismatch')
        if len(indices) == 0:
            return
        _, argsort = np.unique(indices, return_index=True)
        indices = indices[argsort]
        value = value.take(argsort)
        mask = np.zeros(len(self), dtype=np.bool_)
        mask[indices] = True
        data = self._replace_with_mask(self._pa_array, mask, value)
    if isinstance(data, pa.Array):
        data = pa.chunked_array([data])
    self._pa_array = data
    self._cache.clear()

