def _ufunc_inspect_signature_builder(ufunc):
    from inspect import Parameter, Signature
    params = []
    if ufunc.nin == 1:
        params.append(Parameter('x', Parameter.POSITIONAL_ONLY))
    else:
        params.extend((Parameter(f'x{i}', Parameter.POSITIONAL_ONLY) for i in range(1, ufunc.nin + 1)))
    if ufunc.nout == 1:
        out_default = None
    else:
        out_default = (None,) * ufunc.nout
    params.append(Parameter('out', Parameter.POSITIONAL_OR_KEYWORD, default=out_default))
    if ufunc.signature is None:
        params.append(Parameter('where', Parameter.KEYWORD_ONLY, default=True))
    else:
        params.append(Parameter('axes', Parameter.KEYWORD_ONLY, default=_NoValue))
        params.append(Parameter('axis', Parameter.KEYWORD_ONLY, default=_NoValue))
        params.append(Parameter('keepdims', Parameter.KEYWORD_ONLY, default=False))
    params.extend((Parameter('casting', Parameter.KEYWORD_ONLY, default='same_kind'), Parameter('order', Parameter.KEYWORD_ONLY, default='K'), Parameter('dtype', Parameter.KEYWORD_ONLY, default=None), Parameter('subok', Parameter.KEYWORD_ONLY, default=True), Parameter('signature', Parameter.KEYWORD_ONLY, default=None)))
    return Signature(params)

def _dispatch_frame_op(self, right, func: Callable, axis: AxisInt | None=None) -> DataFrame:
    array_op = ops.get_array_op(func)
    right = lib.item_from_zerodim(right)
    if not is_list_like(right):
        bm = self._mgr.apply(array_op, right=right)
        return self._constructor_from_mgr(bm, axes=bm.axes)
    elif isinstance(right, DataFrame):
        assert self.index.equals(right.index)
        assert self.columns.equals(right.columns)
        bm = self._mgr.operate_blockwise(right._mgr, array_op)
        return self._constructor_from_mgr(bm, axes=bm.axes)
    elif isinstance(right, Series) and axis == 1:
        assert right.index.equals(self.columns)
        right = right._values
        assert not isinstance(right, np.ndarray)
        arrays = [array_op(_left, _right) for _left, _right in zip(self._iter_column_arrays(), right, strict=True)]
    elif isinstance(right, Series):
        assert right.index.equals(self.index)
        right = right._values
        arrays = [array_op(left, right) for left in self._iter_column_arrays()]
    else:
        raise NotImplementedError(right)
    return type(self)._from_arrays(arrays, self.columns, self.index, verify_integrity=False)

def get_feature_names_out(self, input_features=None):
    check_is_fitted(self, 'n_features_in_')
    if self.voting == 'soft' and (not self.flatten_transform):
        raise ValueError("get_feature_names_out is not supported when `voting='soft'` and `flatten_transform=False`")
    _check_feature_names_in(self, input_features, generate_names=False)
    class_name = self.__class__.__name__.lower()
    active_names = [name for name, est in self.estimators if est != 'drop']
    if self.voting == 'hard':
        return np.asarray([f'{class_name}_{name}' for name in active_names], dtype=object)
    n_classes = len(self.classes_)
    names_out = [f'{class_name}_{name}{i}' for name in active_names for i in range(n_classes)]
    return np.asarray(names_out, dtype=object)

def _masked_arith_op(x: np.ndarray, y, op) -> np.ndarray:
    xrav = x.ravel()
    if isinstance(y, np.ndarray):
        dtype = find_common_type([x.dtype, y.dtype])
        result = np.empty(x.size, dtype=dtype)
        if len(x) != len(y):
            raise ValueError(x.shape, y.shape)
        ymask = notna(y)
        yrav = y.ravel()
        mask = notna(xrav) & ymask.ravel()
        if mask.any():
            result[mask] = op(xrav[mask], yrav[mask])
    else:
        if not is_scalar(y):
            raise TypeError(f'Cannot broadcast np.ndarray with operand of type {type(y)}')
        result = np.empty(x.size, dtype=x.dtype)
        mask = notna(xrav)
        if op is pow:
            mask = np.where(x == 1, False, mask)
        elif op is roperator.rpow:
            mask = np.where(y == 1, False, mask)
        if mask.any():
            result[mask] = op(xrav[mask], y)
    np.putmask(result, ~mask, np.nan)
    result = result.reshape(x.shape)
    return result

def inverse_transform(self, Y, threshold=None):
    check_is_fitted(self)
    xp, is_array_api = get_namespace(Y)
    if is_array_api and self.sparse_input_ and (not _is_numpy_namespace(xp)):
        raise ValueError(f'`LabelBinarizer` was fitted on a sparse matrix, and therefore cannot inverse transform a {xp.__name__} array back to a sparse matrix.')
    if threshold is None:
        threshold = (self.pos_label + self.neg_label) / 2.0
    if self.y_type_ == 'multiclass':
        y_inv = _inverse_binarize_multiclass(Y, self.classes_, xp=xp)
    else:
        y_inv = _inverse_binarize_thresholding(Y, self.y_type_, self.classes_, threshold, xp=xp)
    if self.sparse_input_:
        y_inv = _align_api_if_sparse(sp.csr_array(y_inv))
    elif sp.issparse(y_inv):
        y_inv = y_inv.toarray()
    return y_inv

