def _reduce_axis1(self, name: str, func, skipna: bool, min_count: int=0) -> Series:
    if name == 'all':
        result = np.ones(len(self), dtype=bool)
        ufunc = np.logical_and
    elif name == 'any':
        result = np.zeros(len(self), dtype=bool)
        ufunc = np.logical_or
    elif name in ('sum', 'mean'):
        result = None
        ufunc = np.add
    elif name == 'prod':
        result = None
        ufunc = np.multiply
    elif name == 'min':
        result = None
        ufunc = np.fmin if skipna else np.minimum
    elif name == 'max':
        result = None
        ufunc = np.fmax if skipna else np.maximum
    else:
        raise NotImplementedError(name)
    for block in self._mgr.blocks:
        vals = block.values
        if name in ('min', 'max'):
            middle = ufunc.reduce(vals, axis=0)
        elif name == 'mean':
            middle = nanops.nansum(vals, axis=0, skipna=skipna, min_count=0)
        elif name in ('sum', 'prod'):
            middle = func(vals, axis=0, skipna=skipna, min_count=0)
        else:
            middle = func(vals, axis=0, skipna=skipna)
        if result is None:
            result = middle.copy()
        else:
            result = ufunc(result, middle)
    if name in ('sum', 'prod', 'mean'):
        if (min_count > 0 or name == 'mean') and result is not None:
            non_null_count = np.zeros(len(self), dtype=np.intp)
            for block in self._mgr.blocks:
                vals = block.values
                if vals.dtype.kind in 'biu':
                    non_null_count += vals.shape[0]
                else:
                    non_null_count += vals.shape[0] - isna(vals).sum(axis=0)
            if name == 'mean':
                null_mask = non_null_count == 0
                result = result.astype('float64')
                result[~null_mask] /= non_null_count[~null_mask]
                result[null_mask] = np.nan
            else:
                null_mask = non_null_count < min_count
                if null_mask.any():
                    if result.dtype.kind not in 'fc':
                        result = result.astype('float64')
                    result[null_mask] = np.nan
    assert result is not None
    res_ser = self._constructor_sliced(result, index=self.index, copy=False)
    return res_ser

@final
@_maybe_return_indexers
def join(self, other: Index, *, how: JoinHow='left', level: Level | None=None, return_indexers: bool=False, sort: bool=False) -> Index | tuple[Index, npt.NDArray[np.intp] | None, npt.NDArray[np.intp] | None]:
    if not isinstance(other, Index):
        warnings.warn(f'Passing {type(other).__name__} to {type(self).__name__}.join is deprecated and will raise in a future version. Pass an Index instead.', Pandas4Warning, stacklevel=find_stack_level())
    other = ensure_index(other)
    sort = sort or how == 'outer'
    if isinstance(self, ABCDatetimeIndex) and isinstance(other, ABCDatetimeIndex):
        if (self.tz is None) ^ (other.tz is None):
            raise TypeError('Cannot join tz-naive with tz-aware DatetimeIndex')
    if not self._is_multi and (not other._is_multi):
        pself, pother = self._maybe_downcast_for_indexing(other)
        if pself is not self or pother is not other:
            return pself.join(pother, how=how, level=level, return_indexers=True, sort=sort)
    if level is None and (self._is_multi or other._is_multi):
        if self.names == other.names:
            pass
        else:
            return self._join_multi(other, how=how)
    if level is not None and (self._is_multi or other._is_multi):
        return self._join_level(other, level, how=how)
    if len(self) == 0 or len(other) == 0:
        try:
            return self._join_empty(other, how, sort)
        except TypeError:
            pass
    if self.dtype != other.dtype:
        dtype = self._find_common_type_compat(other)
        this = self.astype(dtype, copy=False)
        other = other.astype(dtype, copy=False)
        return this.join(other, how=how, return_indexers=True)
    elif isinstance(self, ABCCategoricalIndex) and isinstance(other, ABCCategoricalIndex) and (not self.ordered) and (not self.categories.equals(other.categories)):
        other = Index(other._values.reorder_categories(self.categories), copy=False)
    _validate_join_method(how)
    if self.is_monotonic_increasing and other.is_monotonic_increasing and (self.is_unique or other.is_unique):
        if self._can_use_libjoin and other._can_use_libjoin:
            if self.equals(other):
                ret_index = other if how == 'right' else self
                return (ret_index, None, None)
            try:
                return self._join_monotonic(other, how=how)
            except TypeError:
                pass
        elif isinstance(self, ABCRangeIndex):
            try:
                return self._join_monotonic(other, how=how)
            except (TypeError, NotImplementedError):
                pass
    if self.equals(other) and (self.is_unique or other.is_unique) and (not sort or self.is_monotonic_increasing):
        ret_index = other if how == 'right' else self
        return (ret_index, None, None)
    if not self.is_unique or not other.is_unique:
        return self._join_non_unique(other, how=how, sort=sort)
    return self._join_via_get_indexer(other, how, sort)

