def convert(self, values: np.ndarray, nan_rep, encoding: str, errors: str):
    assert isinstance(values, np.ndarray), type(values)
    if values.dtype.fields is not None:
        values = values[self.cname]
        if not values.flags['ALIGNED']:
            values = values.copy()
    assert self.typ is not None
    if self.dtype is None:
        converted, dtype_name = _get_data_and_dtype_name(values)
        kind = _dtype_to_kind(dtype_name)
    else:
        converted = values
        dtype_name = self.dtype
        kind = self.kind
    assert isinstance(converted, np.ndarray)
    meta = self.meta
    metadata = self.metadata
    ordered = self.ordered
    tz = self.tz
    assert dtype_name is not None
    dtype = dtype_name
    if dtype.startswith('datetime64'):
        if dtype == 'datetime64':
            dtype = 'datetime64[ns]'
        converted = _set_tz(converted, tz, dtype)
    elif dtype.startswith('timedelta64'):
        if dtype == 'timedelta64':
            converted = np.asarray(converted, dtype='m8[ns]')
        else:
            converted = np.asarray(converted, dtype=dtype)
    elif dtype.startswith('period'):
        pdtype = PeriodDtype.construct_from_string(dtype)
        converted = PeriodArray._simple_new(np.asarray(converted, dtype='i8').ravel(), dtype=pdtype)
    elif dtype == 'date':
        try:
            converted = np.asarray([date.fromordinal(v) for v in converted], dtype=object)
        except ValueError:
            converted = np.asarray([date.fromtimestamp(v) for v in converted], dtype=object)
    elif meta == 'category':
        categories = metadata
        codes = converted.ravel()
        if categories is None:
            categories = Index([], dtype=np.float64)
        else:
            mask = isna(categories)
            if mask.any():
                remap = np.full(len(categories), -1, dtype=codes.dtype)
                remap[~mask] = np.arange((~mask).sum(), dtype=codes.dtype)
                categories = categories[~mask]
                codes = np.where(codes < 0, codes, remap[codes])
        converted = Categorical.from_codes(codes, categories=categories, ordered=ordered, validate=False)
    else:
        try:
            converted = converted.astype(dtype, copy=False)
        except TypeError:
            converted = converted.astype('O', copy=False)
    if kind == 'string':
        converted = _unconvert_string_array(converted, nan_rep=nan_rep if nan_rep is not None else 'nan', encoding=encoding, errors=errors)
    return (self.values, converted)

def inverse_transform(self, X, copy=None):
    xp, _, X_device = get_namespace_and_device(X)
    check_is_fitted(self)
    copy = copy if copy is not None else self.copy
    X = check_array(X, accept_sparse='csr', copy=copy, dtype=supported_float_dtypes(xp, X_device), force_writeable=True, ensure_all_finite='allow-nan')
    if sparse.issparse(X):
        if self.with_mean:
            raise ValueError('Cannot uncenter sparse matrices: pass `with_mean=False` instead See docstring for motivation and alternatives.')
        if self.scale_ is not None:
            inplace_column_scale(X, self.scale_)
    else:
        if self.with_std:
            X *= xp.astype(self.scale_, X.dtype)
        if self.with_mean:
            X += xp.astype(self.mean_, X.dtype)
    return X

def _check_large_sparse(X, param_8=False):
    if not param_8:
        supported_indices = ['int32']
        if X.format == 'coo':
            index_keys = ['col', 'row']
        elif X.format in ['csr', 'csc', 'bsr']:
            index_keys = ['indices', 'indptr']
        else:
            return
        for key in index_keys:
            indices_datatype = getattr(X, key).dtype
            if indices_datatype not in supported_indices:
                raise ValueError(f'Only sparse matrices with 32-bit integer indices are accepted. Got {indices_datatype} indices. Please do report a minimal reproducer on scikit-learn issue tracker so that support for your use-case can be studied by maintainers. See: https://scikit-learn.org/dev/developers/minimal_reproducer.html')

@staticmethod
def _parse_subtype(dtype: str) -> tuple[str, bool]:
    xpr = re.compile('Sparse\\[(?P<subtype>[^,]*)(, )?(?P<fill_value>.*?)?\\]$')
    m = xpr.match(dtype)
    has_fill_value = False
    if m:
        subtype = m.groupdict()['subtype']
        has_fill_value = bool(m.groupdict()['fill_value'])
    elif dtype == 'Sparse':
        subtype = 'float64'
    else:
        raise ValueError(f'Cannot parse {dtype}')
    return (subtype, has_fill_value)

