@_fit_context(prefer_skip_nested_validation=False)
def fit(self, X, y=None):
    if self.copy == 'warn':
        warn('The default value of `copy` will change from False to True in 1.10. Explicitly set a value for `copy` to silence this warning.', FutureWarning)
        _copy = False
    else:
        _copy = self.copy
    if self.metric == 'precomputed' and self.store_centers is not None:
        raise ValueError('Cannot store centers when using a precomputed distance matrix.')
    self._metric_params = self.metric_params or {}
    if self.metric != 'precomputed':
        X = validate_data(self, X, accept_sparse=['csr', 'lil'], ensure_all_finite=False, dtype=np.float64)
        self._raw_data = X
        all_finite = True
        try:
            _assert_all_finite(X.data if issparse(X) else X)
        except ValueError:
            all_finite = False
        if not all_finite:
            reduced_X = X.sum(axis=1)
            missing_index = np.isnan(reduced_X).nonzero()[0]
            infinite_index = np.isinf(reduced_X).nonzero()[0]
            finite_index = _get_finite_row_indices(X)
            internal_to_raw = {x: y for x, y in enumerate(finite_index)}
            X = X[finite_index]
    elif issparse(X):
        X = validate_data(self, X, accept_sparse=['csr', 'lil'], dtype=np.float64, force_writeable=True)
    else:
        X = validate_data(self, X, ensure_all_finite=False, dtype=np.float64, force_writeable=True)
        if np.isnan(X).any():
            raise ValueError('np.nan values found in precomputed-dense')
    if X.shape[0] == 1:
        raise ValueError('n_samples=1 while HDBSCAN requires more than one sample')
    self._min_samples = self.min_cluster_size if self.min_samples is None else self.min_samples
    if self._min_samples > X.shape[0]:
        raise ValueError(f'min_samples ({self._min_samples}) must be at most the number of samples in X ({X.shape[0]})')
    mst_func = None
    kwargs = dict(X=X, min_samples=self._min_samples, alpha=self.alpha, metric=self.metric, n_jobs=self.n_jobs, **self._metric_params)
    if self.algorithm == 'kd_tree' and self.metric not in KDTree.valid_metrics:
        raise ValueError(f'{self.metric} is not a valid metric for a KDTree-based algorithm. Please select a different metric.')
    elif self.algorithm == 'ball_tree' and self.metric not in BallTree.valid_metrics:
        raise ValueError(f'{self.metric} is not a valid metric for a BallTree-based algorithm. Please select a different metric.')
    if self.algorithm != 'auto':
        if self.metric != 'precomputed' and issparse(X) and (self.algorithm != 'brute'):
            raise ValueError('Sparse data matrices only support algorithm `brute`.')
        if self.algorithm == 'brute':
            mst_func = _hdbscan_brute
            kwargs['copy'] = _copy
        elif self.algorithm == 'kd_tree':
            mst_func = _hdbscan_prims
            kwargs['algo'] = 'kd_tree'
            kwargs['leaf_size'] = self.leaf_size
        else:
            mst_func = _hdbscan_prims
            kwargs['algo'] = 'ball_tree'
            kwargs['leaf_size'] = self.leaf_size
    elif issparse(X) or self.metric not in FAST_METRICS:
        mst_func = _hdbscan_brute
        kwargs['copy'] = _copy
    elif self.metric in KDTree.valid_metrics:
        mst_func = _hdbscan_prims
        kwargs['algo'] = 'kd_tree'
        kwargs['leaf_size'] = self.leaf_size
    else:
        mst_func = _hdbscan_prims
        kwargs['algo'] = 'ball_tree'
        kwargs['leaf_size'] = self.leaf_size
    self._single_linkage_tree_ = mst_func(**kwargs)
    self.labels_, self.probabilities_ = tree_to_labels(self._single_linkage_tree_, self.min_cluster_size, self.cluster_selection_method, self.allow_single_cluster, self.cluster_selection_epsilon, self.max_cluster_size)
    if self.metric != 'precomputed' and (not all_finite):
        self._single_linkage_tree_ = remap_single_linkage_tree(self._single_linkage_tree_, internal_to_raw, non_finite=set(np.hstack([infinite_index, missing_index])))
        new_labels = np.empty(self._raw_data.shape[0], dtype=np.int32)
        new_labels[finite_index] = self.labels_
        new_labels[infinite_index] = _OUTLIER_ENCODING['infinite']['label']
        new_labels[missing_index] = _OUTLIER_ENCODING['missing']['label']
        self.labels_ = new_labels
        new_probabilities = np.zeros(self._raw_data.shape[0], dtype=np.float64)
        new_probabilities[finite_index] = self.probabilities_
        new_probabilities[infinite_index] = _OUTLIER_ENCODING['infinite']['prob']
        new_probabilities[missing_index] = _OUTLIER_ENCODING['missing']['prob']
        self.probabilities_ = new_probabilities
    if self.store_centers:
        self._weighted_cluster_center(X)
    return self

def _safe_split(estimator, X, y, indices, train_indices=None):
    if get_tags(estimator).input_tags.pairwise:
        if not hasattr(X, 'shape'):
            raise ValueError('Precomputed kernels or affinity matrices have to be passed as arrays or sparse matrices.')
        if X.shape[0] != X.shape[1]:
            raise ValueError('X should be a square kernel matrix')
        if train_indices is None:
            X_subset = X[np.ix_(indices, indices)]
        else:
            X_subset = X[np.ix_(indices, train_indices)]
    else:
        X_subset = _safe_indexing(X, indices)
    if y is not None:
        y_subset = _safe_indexing(y, indices)
    else:
        y_subset = None
    return (X_subset, y_subset)

def _where(self: Self, mask: npt.NDArray[np.bool_], value) -> Self:
    value = self._validate_setitem_value(value)
    res_values = np.where(mask, self._ndarray, value)
    if res_values.dtype != self._ndarray.dtype:
        raise AssertionError('Something has gone wrong, please report a bug at github.com/pandas-dev/pandas/')
    return self._from_backing_data(res_values)

def _kneighbors_reduce_func(self, param_11, start, n_neighbors, return_distance):
    sample_range = np.arange(param_11.shape[0])[:, None]
    neigh_ind = np.argpartition(param_11, n_neighbors - 1, axis=1)
    neigh_ind = neigh_ind[:, :n_neighbors]
    neigh_ind = neigh_ind[sample_range, np.argsort(param_11[sample_range, neigh_ind])]
    if return_distance:
        if self.effective_metric_ == 'euclidean':
            result = (np.sqrt(param_11[sample_range, neigh_ind]), neigh_ind)
        else:
            result = (param_11[sample_range, neigh_ind], neigh_ind)
    else:
        result = neigh_ind
    return result

def _quantile(self, qs: npt.NDArray[np.float64], interpolation: str) -> BaseMaskedArray:
    res = quantile_with_mask(self._data, mask=self._mask, fill_value=np.nan, qs=qs, interpolation=interpolation)
    if self._hasna:
        if self.ndim == 2:
            raise NotImplementedError
        if self.isna().all():
            out_mask = np.ones(res.shape, dtype=bool)
            if is_integer_dtype(self.dtype):
                res = np.zeros(res.shape, dtype=self.dtype.numpy_dtype)
        else:
            out_mask = np.zeros(res.shape, dtype=bool)
    else:
        out_mask = np.zeros(res.shape, dtype=bool)
    return self._maybe_mask_result(res, mask=out_mask)

def _cast_to_stata_types(data: DataFrame) -> DataFrame:
    ws = ''
    conversion_data: tuple[tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type], tuple[type, type, type]] = ((np.bool_, np.int8, np.int8), (np.uint8, np.int8, np.int16), (np.uint16, np.int16, np.int32), (np.uint32, np.int32, np.int64), (np.uint64, np.int64, np.float64))
    float32_max = struct.unpack('<f', b'\xff\xff\xff~')[0]
    float64_max = struct.unpack('<d', b'\xff\xff\xff\xff\xff\xff\xdf\x7f')[0]
    for col in data:
        is_nullable_int = isinstance(data[col].dtype, ExtensionDtype) and data[col].dtype.kind in 'iub'
        orig_missing = data[col].isna()
        if is_nullable_int:
            fv = 0 if data[col].dtype.kind in 'iu' else False
            data[col] = data[col].fillna(fv).astype(data[col].dtype.numpy_dtype)
        elif isinstance(data[col].dtype, ExtensionDtype):
            if getattr(data[col].dtype, 'numpy_dtype', None) is not None:
                data[col] = data[col].astype(data[col].dtype.numpy_dtype)
            elif is_string_dtype(data[col].dtype):
                data[col] = data[col].astype('object')
                data.loc[data[col].isna(), col] = None
        dtype = data[col].dtype
        empty_df = data.shape[0] == 0
        for c_data in conversion_data:
            if dtype == c_data[0]:
                if empty_df or data[col].max() <= np.iinfo(c_data[1]).max:
                    dtype = c_data[1]
                else:
                    dtype = c_data[2]
                if c_data[2] == np.int64:
                    if data[col].max() >= 2 ** 53:
                        ws = precision_loss_doc.format('uint64', 'float64')
                data[col] = data[col].astype(dtype)
        if dtype == np.int8 and (not empty_df):
            if data[col].max() > 100 or data[col].min() < -127:
                data[col] = data[col].astype(np.int16)
        elif dtype == np.int16 and (not empty_df):
            if data[col].max() > 32740 or data[col].min() < -32767:
                data[col] = data[col].astype(np.int32)
        elif dtype == np.int64:
            if empty_df or (data[col].max() <= 2147483620 and data[col].min() >= -2147483647):
                data[col] = data[col].astype(np.int32)
            else:
                data[col] = data[col].astype(np.float64)
                if data[col].max() >= 2 ** 53 or data[col].min() <= -2 ** 53:
                    ws = precision_loss_doc.format('int64', 'float64')
        elif dtype in (np.float32, np.float64):
            if np.isinf(data[col]).any():
                raise ValueError(f'Column {col} contains infinity or -infinitywhich is outside the range supported by Stata.')
            value = data[col].max()
            if dtype == np.float32 and value > float32_max:
                data[col] = data[col].astype(np.float64)
            elif dtype == np.float64:
                if value > float64_max:
                    raise ValueError(f'Column {col} has a maximum value ({value}) outside the range supported by Stata ({float64_max})')
        if is_nullable_int:
            if orig_missing.any():
                sentinel = StataMissingValue.BASE_MISSING_VALUES[data[col].dtype.name]
                data.loc[orig_missing, col] = sentinel
    if ws:
        warnings.warn(ws, PossiblePrecisionLoss, stacklevel=find_stack_level())
    return data

def fit_intercept_only(self, y_true, sample_weight=None):
    y_pred = np.average(y_true, weights=sample_weight, axis=0)
    eps = 10 * np.finfo(y_pred.dtype).eps
    if self.interval_y_pred.low == -np.inf:
        a_min = None
    elif self.interval_y_pred.low_inclusive:
        a_min = self.interval_y_pred.low
    else:
        a_min = self.interval_y_pred.low + eps
    if self.interval_y_pred.high == np.inf:
        a_max = None
    elif self.interval_y_pred.high_inclusive:
        a_max = self.interval_y_pred.high
    else:
        a_max = self.interval_y_pred.high - eps
    if a_min is None and a_max is None:
        return self.link.link(y_pred)
    else:
        return self.link.link(np.clip(y_pred, a_min, a_max))

@array_function_dispatch(_select_dispatcher)
def select(condlist, choicelist, default=0):
    if len(condlist) != len(choicelist):
        raise ValueError('list of cases must be same length as list of conditions')
    if len(condlist) == 0:
        raise ValueError('select with an empty condition list is not possible')
    choicelist = [choice if type(choice) in (int, float, complex) else np.asarray(choice) for choice in choicelist]
    choicelist.append(default if type(default) in (int, float, complex) else np.asarray(default))
    try:
        dtype = np.result_type(*choicelist)
    except TypeError as e:
        msg = f'Choicelist and default value do not have a common dtype: {e}'
        raise TypeError(msg) from None
    condlist = np.broadcast_arrays(*condlist)
    choicelist = np.broadcast_arrays(*choicelist)
    for i, cond in enumerate(condlist):
        if cond.dtype.type is not np.bool:
            raise TypeError(f'invalid entry {i} in condlist: should be boolean ndarray')
    if choicelist[0].ndim == 0:
        result_shape = condlist[0].shape
    else:
        result_shape = np.broadcast_arrays(condlist[0], choicelist[0])[0].shape
    result = np.full(result_shape, choicelist[-1], dtype)
    choicelist = choicelist[-2::-1]
    condlist = condlist[::-1]
    for choice, cond in zip(choicelist, condlist):
        np.copyto(result, choice, where=cond)
    return result

def aggregate(self, func=None, *args, engine=None, engine_kwargs=None, **kwargs) -> DataFrame:
    relabeling, func, columns, order = reconstruct_func(func, **kwargs)
    func = maybe_mangle_lambdas(func)
    if maybe_use_numba(engine):
        kwargs['engine'] = engine
        kwargs['engine_kwargs'] = engine_kwargs
    op = GroupByApply(self, func, args=args, kwargs=kwargs)
    result = op.agg()
    if not is_dict_like(func) and result is not None:
        if not self.as_index and is_list_like(func):
            return result.reset_index()
        else:
            return cast('DataFrame', result)
    elif relabeling:
        result = cast('DataFrame', result)
        result = result.iloc[:, order]
        result = cast('DataFrame', result)
        result.columns = columns
    if result is None:
        if 'engine' in kwargs:
            del kwargs['engine']
            del kwargs['engine_kwargs']
        if maybe_use_numba(engine):
            return self._aggregate_with_numba(func, *args, engine_kwargs=engine_kwargs, **kwargs)
        result = self._python_agg_general(func, *args, **kwargs)
    if not self.as_index:
        result = self._insert_inaxis_grouper(result)
        result.index = default_index(len(result))
    return cast('DataFrame', result)

