    dtype = np.dtype(f'{self.dtype.kind}8[{unit}]')
    new_values = astype_overflowsafe(self._ndarray, dtype, round_ok=round_ok)
    if isinstance(self.dtype, np.dtype):
        new_dtype = new_values.dtype
    else:
        tz = cast('DatetimeArray', self).tz
        new_dtype = DatetimeTZDtype(tz=tz, unit=unit)
    return type(self)._simple_new(new_values, dtype=new_dtype)

def load_sample_images():
    try:
        from PIL import Image
    except ImportError:
        raise ImportError('The Python Imaging Library (PIL) is required to load data from jpeg files. Please refer to https://pillow.readthedocs.io/en/stable/installation.html for installing PIL.')
    descr = load_descr('README.txt', descr_module=IMAGES_MODULE)
    filenames, images = ([], [])
    jpg_paths = sorted((resource for resource in resources.files(IMAGES_MODULE).iterdir() if resource.is_file() and resource.match('*.jpg')))
    for path in jpg_paths:
        filenames.append(str(path))
        with path.open('rb') as image_file:
            pil_image = Image.open(image_file)
            image = np.asarray(pil_image)
        images.append(image)
    return Bunch(images=images, filenames=filenames, DESCR=descr)

@available_if(_final_estimator_has('score'))
def score(self, item, y=None, sample_weight=None, **params):
    check_is_fitted(self)
    Xt = item
    if not _routing_enabled():
        for _, name, transform in self._iter(with_final=False):
            Xt = transform.transform(Xt)
        score_params = {}
        if sample_weight is not None:
            score_params['sample_weight'] = sample_weight
        return self.steps[-1][1].score(Xt, y, **score_params)
    routed_params = process_routing(self, 'score', sample_weight=sample_weight, **params)
    Xt = item
    for _, name, transform in self._iter(with_final=False):
        Xt = transform.transform(Xt, **routed_params[name].transform)
    return self.steps[-1][1].score(Xt, y, **routed_params[self.steps[-1][0]].score)

