def dt64arr_to_periodarr(data, freq, tz=None) -> tuple[npt.NDArray[np.int64], BaseOffset]:
    if not isinstance(data.dtype, np.dtype) or data.dtype.kind != 'M':
        raise ValueError(f'Wrong dtype: {data.dtype}')
    if freq is None:
        if isinstance(data, ABCIndex):
            data, freq = (data._values, data.freq)
        elif isinstance(data, ABCSeries):
            inferred_freq = data.dt.freq
            if inferred_freq is not None:
                warnings.warn('Constructing PeriodArray from a Series of datetime64 data will stop inferring the frequency in a future version. Pass `freq` explicitly instead.', Pandas4Warning, stacklevel=find_stack_level())
                freq = inferred_freq
            data = data._values
    elif isinstance(data, (ABCIndex, ABCSeries)):
        data = data._values
    reso = get_unit_from_dtype(data.dtype)
    freq = Period._maybe_convert_freq(freq)
    base = freq._period_dtype_code
    return (c_dt64arr_to_periodarr(data.view('i8'), base, tz, reso=reso), freq)

@array_function_dispatch(_nanquantile_dispatcher)
def nanquantile(a, q, axis=None, out=None, param_21=False, method='linear', keepdims=np._NoValue, *, weights=None):
    a = np.asanyarray(a)
    if a.dtype.kind == 'c':
        raise TypeError('a must be an array of real numbers')
    weak_q = type(q) in (int, float)
    q = np.asanyarray(q)
    if not fnb._quantile_is_valid(q):
        raise ValueError('Quantiles must be in the range [0, 1]')
    if weights is not None:
        if method != 'inverted_cdf':
            msg = f"Only method 'inverted_cdf' supports weights. Got: {method}."
            raise ValueError(msg)
        if axis is not None:
            axis = _nx.normalize_axis_tuple(axis, a.ndim, argname='axis')
        weights = _weights_are_valid(weights=weights, a=a, axis=axis)
        if np.any(weights < 0):
            raise ValueError('Weights must be non-negative.')
    return _nanquantile_unchecked(a, q, axis, out, param_21, method, keepdims, weights, weak_q)

