def _insert_error_scores(results, error_score):
    successful_score = None
    failed_indices = []
    for i, result in enumerate(results):
        if result['fit_error'] is not None:
            failed_indices.append(i)
        elif successful_score is None:
            successful_score = result['test_scores']
    if isinstance(successful_score, dict):
        formatted_error = {name: error_score for name in successful_score}
        for i in failed_indices:
            results[i]['test_scores'] = formatted_error.copy()
            if 'train_scores' in results[i]:
                results[i]['train_scores'] = formatted_error.copy()

def _check_timedeltalike_freq_compat(self, other):
    assert self.dtype._is_tick_like()
    dtype = np.dtype(f'm8[{self.dtype._td64_unit}]')
    if isinstance(other, (timedelta, np.timedelta64, Tick)):
        td = np.asarray(Timedelta(other).asm8)
    else:
        td = np.asarray(other)
    try:
        delta = astype_overflowsafe(td, dtype=dtype, copy=False, round_ok=False)
    except ValueError as err:
        raise raise_on_incompatible(self, other) from err
    delta = delta.view('i8')
    return lib.item_from_zerodim(delta)

def predict(self, X):
    check_is_fitted(self, '_fit_method')
    if self.weights == 'uniform':
        if self._fit_method == 'brute' and ArgKminClassMode.is_usable_for(X, self._fit_X, self.metric):
            probabilities = self.predict_proba(X)
            if self.outputs_2d_:
                return np.stack([self.classes_[idx][np.argmax(probas, axis=1)] for idx, probas in enumerate(probabilities)], axis=1)
            return self.classes_[np.argmax(probabilities, axis=1)]
        neigh_ind = self.kneighbors(X, return_distance=False)
        neigh_dist = None
    else:
        neigh_dist, neigh_ind = self.kneighbors(X)
    classes_ = self.classes_
    _y = self._y
    if not self.outputs_2d_:
        _y = self._y.reshape((-1, 1))
        classes_ = [self.classes_]
    n_outputs = len(classes_)
    n_queries = _num_samples(self._fit_X if X is None else X)
    weights = _get_weights(neigh_dist, self.weights)
    if weights is not None and _all_with_any_reduction_axis_1(weights, value=0):
        raise ValueError("All neighbors of some sample is getting zero weights. Please modify 'weights' to avoid this case if you are using a user-defined function.")
    y_pred = np.empty((n_queries, n_outputs), dtype=classes_[0].dtype)
    for k, classes_k in enumerate(classes_):
        if weights is None:
            mode, _ = _mode(_y[neigh_ind, k], axis=1)
        else:
            mode, _ = weighted_mode(_y[neigh_ind, k], weights, axis=1)
        mode = np.asarray(mode.ravel(), dtype=np.intp)
        y_pred[:, k] = classes_k.take(mode)
    if not self.outputs_2d_:
        y_pred = y_pred.ravel()
    return y_pred

def handle_user_exception(self, ctx: AppContext, e: Exception) -> HTTPException | ft.ResponseReturnValue:
    if isinstance(e, BadRequestKeyError) and (self.debug or self.config['TRAP_BAD_REQUEST_ERRORS']):
        e.show_exception = True
    if isinstance(e, HTTPException) and (not self.trap_http_exception(e)):
        return self.handle_http_exception(ctx, e)
    handler = self._find_error_handler(e, ctx.request.blueprints)
    if handler is None:
        raise
    return self.ensure_sync(handler)(e)

