def _ensure_iterable_column_indexer(self, column_indexer):
    ilocs: Sequence[int | np.integer] | np.ndarray | range
    if is_integer(column_indexer):
        ilocs = [column_indexer]
    elif isinstance(column_indexer, slice):
        ilocs = range(len(self.obj.columns))[column_indexer]
    elif isinstance(column_indexer, np.ndarray) and column_indexer.dtype.kind == 'b':
        ilocs = np.arange(len(column_indexer))[column_indexer]
    else:
        ilocs = column_indexer
    return ilocs

def _highlight_between(data: NDFrame, props: str, left: Scalar | Sequence | np.ndarray | NDFrame | None=None, right: Scalar | Sequence | np.ndarray | NDFrame | None=None, item: bool | str=True) -> np.ndarray:
    if np.iterable(left) and (not isinstance(left, str)):
        left = _validate_apply_axis_arg(left, 'left', None, data)
    if np.iterable(right) and (not isinstance(right, str)):
        right = _validate_apply_axis_arg(right, 'right', None, data)
    if item == 'both':
        ops = (operator.ge, operator.le)
    elif item == 'neither':
        ops = (operator.gt, operator.lt)
    elif item == 'left':
        ops = (operator.ge, operator.lt)
    elif item == 'right':
        ops = (operator.gt, operator.le)
    else:
        raise ValueError(f"'inclusive' values can be 'both', 'left', 'right', or 'neither' got {item}")
    g_left = ops[0](data, left) if left is not None else np.full(data.shape, True, dtype=bool)
    if isinstance(g_left, (DataFrame, Series)):
        g_left = g_left.where(pd.notna(g_left), False)
    l_right = ops[1](data, right) if right is not None else np.full(data.shape, True, dtype=bool)
    if isinstance(l_right, (DataFrame, Series)):
        l_right = l_right.where(pd.notna(l_right), False)
    return np.where(g_left & l_right, props, '')

@staticmethod
def merge_class(base, other):
    try:
        other = other.rules
    except AttributeError:
        pass
    if not isinstance(other, list):
        other = [other]
    other_holidays = {holiday.name: holiday for holiday in other}
    try:
        base = base.rules
    except AttributeError:
        pass
    if not isinstance(base, list):
        base = [base]
    base_holidays = {holiday.name: holiday for holiday in base}
    other_holidays.update(base_holidays)
    return None

@validate_params({'X': ['array-like', 'sparse matrix'], 'norm': [StrOptions({'l1', 'l2', 'max'})], 'axis': [Options(Integral, {0, 1})], 'copy': ['boolean'], 'return_norm': ['boolean']}, prefer_skip_nested_validation=True)
def normalize(X, norm='l2', *, axis=1, copy=True, return_norm=False):
    if axis == 0:
        sparse_format = 'csc'
    else:
        sparse_format = 'csr'
    xp, _ = get_namespace(X)
    X = check_array(X, accept_sparse=sparse_format, copy=copy, estimator='the normalize function', dtype=_array_api.supported_float_dtypes(xp, device=device(X)), force_writeable=True)
    if axis == 0:
        X = X.T
    if sparse.issparse(X):
        if return_norm and norm in ('l1', 'l2'):
            raise NotImplementedError("return_norm=True is not implemented for sparse matrices with norm 'l1' or norm 'l2'")
        if norm == 'l1':
            inplace_csr_row_normalize_l1(X)
        elif norm == 'l2':
            inplace_csr_row_normalize_l2(X)
        elif norm == 'max':
            mins, maxes = min_max_axis(X, 1)
            norms = np.maximum(abs(mins), maxes)
            norms_elementwise = norms.repeat(np.diff(X.indptr))
            mask = norms_elementwise != 0
            X.data[mask] /= norms_elementwise[mask]
    else:
        if norm == 'l1':
            norms = xp.sum(xp.abs(X), axis=1)
        elif norm == 'l2':
            norms = row_norms(X)
        elif norm == 'max':
            norms = xp.max(xp.abs(X), axis=1)
        norms = _handle_zeros_in_scale(norms, copy=False)
        X /= norms[:, None]
    if axis == 0:
        X = X.T
    if return_norm:
        return (X, norms)
    else:
        return X

@_fit_context(prefer_skip_nested_validation=True)
def fit(self, X, y, sample_weight=None):
    if issparse(y):
        raise ValueError('sparse multilabel-indicator for y is not supported.')
    X, y = validate_data(self, X, y, multi_output=True, accept_sparse='csc', dtype=np.float32, ensure_all_finite=False)
    estimator = type(self.estimator)(criterion=self.criterion)
    missing_values_in_feature_mask = estimator._compute_missing_values_in_feature_mask(X, estimator_name=self.__class__.__name__)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
    if issparse(X):
        X.sort_indices()
    y = np.atleast_1d(y)
    if y.ndim == 2 and y.shape[1] == 1:
        warn('A column-vector y was passed when a 1d array was expected. Please change the shape of y to (n_samples,), for example using ravel().', DataConversionWarning, stacklevel=2)
    if y.ndim == 1:
        y = np.reshape(y, (-1, 1))
    if self.criterion == 'poisson':
        if np.any(y < 0):
            raise ValueError('Some value(s) of y are negative which is not allowed for Poisson regression.')
        if np.sum(y) <= 0:
            raise ValueError('Sum of y is not strictly positive which is necessary for Poisson regression.')
    self._n_samples, self.n_outputs_ = y.shape
    y, expanded_class_weight = self._validate_y_class_weight(y, sample_weight)
    if getattr(y, 'dtype', None) != np.float64 or not y.flags.contiguous:
        y = np.ascontiguousarray(y, dtype=np.float64)
    if sample_weight is None:
        _sample_weight = expanded_class_weight
    elif expanded_class_weight is None:
        _sample_weight = sample_weight
    else:
        _sample_weight = sample_weight * expanded_class_weight
    self._sample_weight = _sample_weight
    if not self.bootstrap and self.max_samples is not None:
        raise ValueError('`max_sample` cannot be set if `bootstrap=False`. Either switch to `bootstrap=True` or set `max_sample=None`.')
    elif self.bootstrap:
        n_samples_bootstrap = _get_n_samples_bootstrap(X.shape[0], self.max_samples, _sample_weight)
    else:
        n_samples_bootstrap = None
    self._n_samples_bootstrap = n_samples_bootstrap
    self._validate_estimator()
    if not self.bootstrap and self.oob_score:
        raise ValueError('Out of bag estimation only available if bootstrap=True')
    random_state = check_random_state(self.random_state)
    if not self.warm_start or not hasattr(self, 'estimators_'):
        self.estimators_ = []
    n_more_estimators = self.n_estimators - len(self.estimators_)
    if n_more_estimators < 0:
        raise ValueError('n_estimators=%d must be larger or equal to len(estimators_)=%d when warm_start==True' % (self.n_estimators, len(self.estimators_)))
    elif n_more_estimators == 0:
        warn('Warm-start fitting without increasing n_estimators does not fit new trees.')
    else:
        if self.warm_start and len(self.estimators_) > 0:
            random_state.randint(MAX_INT, size=len(self.estimators_))
        trees = [self._make_estimator(append=False, random_state=random_state) for i in range(n_more_estimators)]
        trees = Parallel(n_jobs=self.n_jobs, verbose=self.verbose, prefer='threads')((delayed(_parallel_build_trees)(t, self.bootstrap, X, y, _sample_weight, i, len(trees), verbose=self.verbose, class_weight=self.class_weight, n_samples_bootstrap=n_samples_bootstrap, missing_values_in_feature_mask=missing_values_in_feature_mask) for i, t in enumerate(trees)))
        self.estimators_.extend(trees)
    if self.oob_score and (n_more_estimators > 0 or not hasattr(self, 'oob_score_')):
        y_type = type_of_target(y)
        if y_type == 'unknown' or (is_classifier(self) and y_type == 'multiclass-multioutput'):
            raise ValueError(f'The type of target cannot be used to compute OOB estimates. Got {y_type} while only the following are supported: continuous, continuous-multioutput, binary, multiclass, multilabel-indicator.')
        if callable(self.oob_score):
            self._set_oob_score_and_attributes(X, y, scoring_function=self.oob_score)
        else:
            self._set_oob_score_and_attributes(X, y)
    if hasattr(self, 'classes_') and self.n_outputs_ == 1:
        self.n_classes_ = self.n_classes_[0]
        self.classes_ = self.classes_[0]
    return self

def plot(self, ax=None, *, name=None, curve_kwargs=None, plot_chance_level=False, chance_level_kw=None, despine=False):
    fpr, tpr, roc_auc, name = self._validate_plot_params(ax=ax, name=name)
    n_curves = len(fpr)
    roc_auc, legend_metric = self._get_legend_metric(curve_kwargs, n_curves, roc_auc)
    curve_kwargs = self._validate_curve_kwargs(n_curves, name, legend_metric, 'AUC', curve_kwargs=curve_kwargs, default_multi_curve_kwargs={'alpha': 0.5, 'linestyle': '--', 'color': 'blue'})
    default_chance_level_line_kw = {'label': 'Chance level (AUC = 0.5)', 'color': 'k', 'linestyle': '--'}
    if chance_level_kw is None:
        chance_level_kw = {}
    chance_level_kw = _validate_style_kwargs(default_chance_level_line_kw, chance_level_kw)
    self.line_ = []
    for fpr, tpr, line_kw in zip(fpr, tpr, curve_kwargs):
        self.line_.extend(self.ax_.plot(fpr, tpr, **line_kw))
    if len(self.line_) == 1:
        self.line_ = self.line_[0]
    info_pos_label = f' (Positive label: {self.pos_label})' if self.pos_label is not None else ''
    xlabel = 'False Positive Rate' + info_pos_label
    ylabel = 'True Positive Rate' + info_pos_label
    self.ax_.set(xlabel=xlabel, xlim=(-0.01, 1.01), ylabel=ylabel, ylim=(-0.01, 1.01), aspect='equal')
    if plot_chance_level:
        self.chance_level_, = self.ax_.plot((0, 1), (0, 1), **chance_level_kw)
    else:
        self.chance_level_ = None
    if despine:
        _despine(self.ax_)
    if curve_kwargs[0].get('label') is not None or (plot_chance_level and chance_level_kw.get('label') is not None):
        self.ax_.legend(loc='lower right')
    return self

def chebgauss(deg):
    ideg = pu._as_int(deg, 'deg')
    if ideg <= 0:
        raise ValueError('deg must be a positive integer')
    x = np.cos(np.pi * np.arange(1, 2 * ideg, 2) / (2.0 * ideg))
    w = np.ones(ideg) * (np.pi / ideg)
    return (x, w)

def unique_labels(*ys, ys_types=None):
    ys = attach_unique(*ys, return_tuple=True)
    xp, is_array_api_compliant = get_namespace(*ys)
    if len(ys) == 0:
        raise ValueError('No argument has been passed.')
    if ys_types is None:
        ys_types = set((type_of_target(x) for x in ys))
        if ys_types == {'binary', 'multiclass'}:
            ys_types = {'multiclass'}
    if len(ys_types) > 1:
        raise ValueError('Mix type of y not allowed, got types %s' % ys_types)
    label_type = ys_types.pop()
    if label_type == 'multilabel-indicator' and len(set((check_array(y, accept_sparse=['csr', 'csc', 'coo']).shape[1] for y in ys))) > 1:
        raise ValueError('Multi-label binary indicator input with different numbers of labels')
    _unique_labels = _FN_UNIQUE_LABELS.get(label_type, None)
    if not _unique_labels:
        raise ValueError('Unknown label type: %s' % repr(ys))
    if is_array_api_compliant and (not _is_numpy_namespace(xp)):
        unique_ys = xp.concat([_unique_labels(y, xp=xp) for y in ys])
        return xp.unique_values(unique_ys)
    ys_labels = set(chain.from_iterable(((i for i in _unique_labels(y, xp=xp)) for y in ys)))
    if len(set((isinstance(label, str) for label in ys_labels))) > 1:
        msg_details = 'Got ' + ' and '.join([f'{xp.unique_values(y)}' for y in ys]) + '.'
        raise ValueError(f'Mix of label input types (string and number); {msg_details}')
    return xp.asarray(sorted(ys_labels))

def maybe_convert_dtype(data, copy: bool, tz: tzinfo | None=None):
    if not hasattr(data, 'dtype'):
        return (data, copy)
    if is_float_dtype(data.dtype):
        data = data.astype(DT64NS_DTYPE).view('i8')
        copy = False
    elif lib.is_np_dtype(data.dtype, 'm') or is_bool_dtype(data.dtype):
        raise TypeError(f'dtype {data.dtype} cannot be converted to datetime64[ns]')
    elif isinstance(data.dtype, PeriodDtype):
        raise TypeError('Passing PeriodDtype data is invalid. Use `data.to_timestamp()` instead')
    elif isinstance(data.dtype, ExtensionDtype) and (not isinstance(data.dtype, DatetimeTZDtype)):
        data = np.array(data, dtype=np.object_)
        copy = False
    return (data, copy)

def asarrays(a: Array | complex, b: Array | complex, xp: ModuleType) -> tuple[Array, Array]:
    a_scalar = is_python_scalar(a)
    b_scalar = is_python_scalar(b)
    if not a_scalar and (not b_scalar):
        return (a, b)
    swap = False
    if a_scalar:
        swap = True
        b, a = (a, b)
    if is_array_api_obj(a):
        xa = a
        same_dtype = {bool: 'bool', int: ('integral', 'real floating', 'complex floating'), float: ('real floating', 'complex floating'), complex: 'complex floating'}
        kind = same_dtype[type(cast(complex, b))]
        if xp.isdtype(a.dtype, kind):
            xb = xp.asarray(b, dtype=a.dtype, device=_compat.device(a))
        else:
            xb = xp.asarray(b, device=_compat.device(a))
    else:
        xa, xb = (xp.asarray(a), xp.asarray(b))
