@_fit_context(prefer_skip_nested_validation=True)
def fit(self, entry, y=None):
    entry = validate_data(self, entry)
    bandwidth = self.bandwidth
    if bandwidth is None:
        bandwidth = estimate_bandwidth(entry, n_jobs=self.n_jobs)
    seeds = self.seeds
    if seeds is None:
        if self.bin_seeding:
            seeds = get_bin_seeds(entry, bandwidth, self.min_bin_freq)
        else:
            seeds = entry
    n_samples, n_features = entry.shape
    center_intensity_dict = {}
    nbrs = NearestNeighbors(radius=bandwidth, n_jobs=1).fit(entry)
    all_res = Parallel(n_jobs=self.n_jobs)((delayed(_mean_shift_single_seed)(seed, entry, nbrs, self.max_iter) for seed in seeds))
    for i in range(len(seeds)):
        if all_res[i][1]:
            center_intensity_dict[all_res[i][0]] = all_res[i][1]
    self.n_iter_ = max([x[2] for x in all_res])
    if not center_intensity_dict:
        raise ValueError('No point was within bandwidth=%f of any seed. Try a different seeding strategy                              or increase the bandwidth.' % bandwidth)
    sorted_by_intensity = sorted(center_intensity_dict.items(), key=lambda tup: (tup[1], tup[0]), reverse=True)
    sorted_centers = np.array([tup[0] for tup in sorted_by_intensity])
    unique = np.ones(len(sorted_centers), dtype=bool)
    nbrs = NearestNeighbors(radius=bandwidth, n_jobs=self.n_jobs).fit(sorted_centers)
    for i, center in enumerate(sorted_centers):
        if unique[i]:
            neighbor_idxs = nbrs.radius_neighbors([center], return_distance=False)[0]
            unique[neighbor_idxs] = 0
            unique[i] = 1
    cluster_centers = sorted_centers[unique]
    nbrs = NearestNeighbors(n_neighbors=1, n_jobs=self.n_jobs).fit(cluster_centers)
    labels = np.zeros(n_samples, dtype=int)
    distances, idxs = nbrs.kneighbors(entry)
    if self.cluster_all:
        labels = idxs.flatten()
    else:
        labels.fill(-1)
        bool_selector = distances.flatten() <= bandwidth
        labels[bool_selector] = idxs.flatten()[bool_selector]
    self.cluster_centers_, self.labels_ = (cluster_centers, labels)
    return self

def value_counts(self, subset: IndexLabel | None=None, normalize: bool=False, sort: bool=True, ascending: bool=False, dropna: bool=True) -> Series:
    if subset is None:
        subset = self.columns.tolist()
    name = 'proportion' if normalize else 'count'
    counts = self.groupby(subset, sort=False, dropna=dropna, observed=False)._grouper.size()
    counts.name = name
    if sort:
        counts = counts.sort_values(ascending=ascending, kind='stable')
    if normalize:
        counts /= counts.sum()
    if is_list_like(subset) and len(subset) == 1:
        counts.index = MultiIndex.from_arrays([counts.index], names=[counts.index.name])
    return counts

@array_function_dispatch(_histogram_dispatcher)
def histogram(a, bins=10, range=None, density=None, weights=None):
    a, weights = _ravel_and_check_weights(a, weights)
    bin_edges, uniform_bins = _get_bin_edges(a, bins, range, weights)
    if weights is None:
        ntype = np.dtype(np.intp)
    else:
        ntype = weights.dtype
    BLOCK = 65536
    simple_weights = weights is None or np.can_cast(weights.dtype, np.double) or np.can_cast(weights.dtype, complex)
    if uniform_bins is not None and simple_weights:
        first_edge, last_edge, n_equal_bins = uniform_bins
        n = np.zeros(n_equal_bins, ntype)
        norm_numerator = n_equal_bins
        norm_denom = _unsigned_subtract(last_edge, first_edge)
        for i in _range(0, len(a), BLOCK):
            tmp_a = a[i:i + BLOCK]
            if weights is None:
                tmp_w = None
            else:
                tmp_w = weights[i:i + BLOCK]
            keep = tmp_a >= first_edge
            keep &= tmp_a <= last_edge
            if not np.logical_and.reduce(keep):
                tmp_a = tmp_a[keep]
                if tmp_w is not None:
                    tmp_w = tmp_w[keep]
            tmp_a = tmp_a.astype(bin_edges.dtype, copy=False)
            f_indices = _unsigned_subtract(tmp_a, first_edge) / norm_denom * norm_numerator
            indices = f_indices.astype(np.intp)
            indices[indices == n_equal_bins] -= 1
            decrement = tmp_a < bin_edges[indices]
            indices[decrement] -= 1
            increment = (tmp_a >= bin_edges[indices + 1]) & (indices != n_equal_bins - 1)
            indices[increment] += 1
            if ntype.kind == 'c':
                n.real += np.bincount(indices, weights=tmp_w.real, minlength=n_equal_bins)
                n.imag += np.bincount(indices, weights=tmp_w.imag, minlength=n_equal_bins)
            else:
                n += np.bincount(indices, weights=tmp_w, minlength=n_equal_bins).astype(ntype)
    else:
        cum_n = np.zeros(bin_edges.shape, ntype)
        if weights is None:
            for i in _range(0, len(a), BLOCK):
                sa = np.sort(a[i:i + BLOCK])
                cum_n += _search_sorted_inclusive(sa, bin_edges)
        else:
            zero = np.zeros(1, dtype=ntype)
            for i in _range(0, len(a), BLOCK):
                tmp_a = a[i:i + BLOCK]
                tmp_w = weights[i:i + BLOCK]
                sorting_index = np.argsort(tmp_a)
                sa = tmp_a[sorting_index]
                sw = tmp_w[sorting_index]
                cw = np.concatenate((zero, sw.cumsum()))
                bin_index = _search_sorted_inclusive(sa, bin_edges)
                cum_n += cw[bin_index]
        n = np.diff(cum_n)
    if density:
        db = np.array(np.diff(bin_edges), float)
        return (n / db / n.sum(), bin_edges)
    return (n, bin_edges)

