def _sym_decorrelation(W):
    s, u = linalg.eigh(np.dot(W, W.T))
    s = np.clip(s, a_min=np.finfo(W.dtype).tiny, a_max=None)
    return np.linalg.multi_dot([u * (1.0 / np.sqrt(s)), u.T, W])

def _determine_key_type(identifier, accept_slice=True):
    err_msg = 'No valid specification of the columns. Only a scalar, list or slice of all integers or all strings, or boolean mask is allowed'
    dtype_to_str = {int: 'int', str: 'str', bool: 'bool', np.bool_: 'bool'}
    array_dtype_to_str = {'i': 'int', 'u': 'int', 'b': 'bool', 'O': 'str', 'U': 'str', 'S': 'str'}
    if identifier is None:
        return None
    if isinstance(identifier, tuple(dtype_to_str.keys())):
        try:
            return dtype_to_str[type(identifier)]
        except KeyError:
            raise ValueError(err_msg)
    if isinstance(identifier, slice):
        if not accept_slice:
            raise TypeError('Only array-like or scalar are supported. A Python slice was given.')
        if identifier.start is None and identifier.stop is None:
            return None
        key_start_type = _determine_key_type(identifier.start)
        key_stop_type = _determine_key_type(identifier.stop)
        if key_start_type is not None and key_stop_type is not None:
            if key_start_type != key_stop_type:
                raise ValueError(err_msg)
        if key_start_type is not None:
            return key_start_type
        return key_stop_type
    if isinstance(identifier, (list, tuple)):
        unique_key = set(identifier)
        key_type = {_determine_key_type(elt) for elt in unique_key}
        if not key_type:
            return None
        if len(key_type) != 1:
            raise ValueError(err_msg)
        return key_type.pop()
    if hasattr(identifier, 'dtype'):
        xp, is_array_api = get_namespace(identifier)
        if is_array_api and (not _is_numpy_namespace(xp)):
            if xp.isdtype(identifier.dtype, 'bool'):
                return 'bool'
            elif xp.isdtype(identifier.dtype, 'integral'):
                return 'int'
            else:
                raise ValueError(err_msg)
        else:
            try:
                return array_dtype_to_str[identifier.dtype.kind]
            except KeyError:
                raise ValueError(err_msg)
    raise ValueError(err_msg)

