def to_records(self, index: bool=True, column_dtypes=None, index_dtypes=None) -> np.rec.recarray:
    if index:
        ix_vals = [np.asarray(self.index.get_level_values(i)) for i in range(self.index.nlevels)]
        arrays = ix_vals + [np.asarray(self.iloc[:, i]) for i in range(len(self.columns))]
        index_names = list(self.index.names)
        if isinstance(self.index, MultiIndex):
            index_names = com.fill_missing_names(index_names)
        elif index_names[0] is None:
            index_names = ['index']
        names = [str(name) for name in itertools.chain(index_names, self.columns)]
    else:
        arrays = [np.asarray(self.iloc[:, i]) for i in range(len(self.columns))]
        names = [str(c) for c in self.columns]
        index_names = []
    index_len = len(index_names)
    formats = []
    for i, v in enumerate(arrays):
        index_int = i
        if index_int < index_len:
            dtype_mapping = index_dtypes
            name = index_names[index_int]
        else:
            index_int -= index_len
            dtype_mapping = column_dtypes
            name = self.columns[index_int]
        if is_dict_like(dtype_mapping):
            if name in dtype_mapping:
                dtype_mapping = dtype_mapping[name]
            elif index_int in dtype_mapping:
                dtype_mapping = dtype_mapping[index_int]
            else:
                dtype_mapping = None
        if dtype_mapping is None:
            formats.append(v.dtype)
        elif isinstance(dtype_mapping, (type, np.dtype, str)):
            formats.append(dtype_mapping)
        else:
            element = 'row' if i < index_len else 'column'
            msg = f'Invalid dtype {dtype_mapping} specified for {element} {name}'
            raise ValueError(msg)
    return np.rec.fromarrays(arrays, dtype={'names': names, 'formats': formats})

@array_function_dispatch(_tensordot_dispatcher)
def tensordot(index, b, axes=2):
    try:
        iter(axes)
    except Exception:
        axes_a = list(range(-axes, 0))
        axes_b = list(range(axes))
    else:
        axes_a, axes_b = axes
    try:
        na = len(axes_a)
        axes_a = list(axes_a)
    except TypeError:
        axes_a = [axes_a]
        na = 1
    try:
        nb = len(axes_b)
        axes_b = list(axes_b)
    except TypeError:
        axes_b = [axes_b]
        nb = 1
    if len(set(axes_a)) != len(axes_a):
        raise ValueError('duplicate axes are not allowed in tensordot')
    if len(set(axes_b)) != len(axes_b):
        raise ValueError('duplicate axes are not allowed in tensordot')
    index, b = (asarray(index), asarray(b))
    as_ = index.shape
    nda = index.ndim
    bs = b.shape
    ndb = b.ndim
    equal = True
    if na != nb:
        equal = False
    else:
        for k in range(na):
            if as_[axes_a[k]] != bs[axes_b[k]]:
                equal = False
                break
            if axes_a[k] < 0:
                axes_a[k] += nda
            if axes_b[k] < 0:
                axes_b[k] += ndb
    if not equal:
        raise ValueError('shape-mismatch for sum')
    notin = [k for k in range(nda) if k not in axes_a]
    newaxes_a = notin + axes_a
    N2 = math.prod((as_[axis] for axis in axes_a))
    newshape_a = (math.prod((as_[ax] for ax in notin)), N2)
    olda = [as_[axis] for axis in notin]
    notin = [k for k in range(ndb) if k not in axes_b]
    newaxes_b = axes_b + notin
    N2 = math.prod((bs[axis] for axis in axes_b))
    newshape_b = (N2, math.prod((bs[ax] for ax in notin)))
    oldb = [bs[axis] for axis in notin]
    at = index.transpose(newaxes_a).reshape(newshape_a)
    bt = b.transpose(newaxes_b).reshape(newshape_b)
    res = dot(at, bt)
    return res.reshape(olda + oldb)

def _op(self, at_op: _AtOp, in_place_op: Callable[[Array, Array | complex], Array] | None, out_of_place_op: Callable[[Array, Array], Array] | None, y: Array | complex, /, copy: bool | None, xp: ModuleType | None) -> Array:
    from ._funcs import apply_where
    x, idx = (self._x, self._idx)
    xp = array_namespace(x, y) if xp is None else xp
    if isinstance(idx, Undef):
        msg = 'Index has not been set.\nUsage: either\n    at(x, idx).set(value)\nor\n    at(x)[idx].set(value)\n(same for all other methods).'
        raise ValueError(msg)
    if copy not in (True, False, None):
        msg = f'copy must be True, False, or None; got {copy!r}'
        raise ValueError(msg)
    writeable = None if copy else is_writeable_array(x)
    if (is_dask_array(idx) or is_jax_array(idx)) and idx.dtype == xp.bool and (idx.shape == x.shape):
        y_xp = xp.asarray(y, dtype=x.dtype, device=_compat.device(x))
        if y_xp.ndim == 0:
            if out_of_place_op:
                out = apply_where(idx, (x, y_xp), out_of_place_op, fill_value=x, xp=xp)
                out = xp.astype(out, x.dtype, copy=False)
            else:
                out = xp.where(idx, y_xp, x)
            if copy is False:
                x[()] = out
                return x
            return out
    if copy or (copy is None and (not writeable)):
        if is_jax_array(x):
            func = cast(Callable[[Array | complex], Array], getattr(x.at[idx], at_op.value))
            out = func(y)
            return xp.astype(out, x.dtype, copy=False)
        x = xp.asarray(x, copy=True)
        assert not writeable
        writeable = None
    if writeable is None:
        writeable = is_writeable_array(x)
    if not writeable:
        msg = f"Can't update read-only array {x}"
        raise ValueError(msg)
    if is_torch_array(y):
        y = xp.astype(y, x.dtype, copy=False)
    if in_place_op:
        x[idx] = in_place_op(x[idx], y)
    else:
        x[idx] = y
    return x

@validate_params({'X': ['array-like', 'sparse matrix'], 'Y': ['array-like', 'sparse matrix', None], 'dense_output': ['boolean']}, prefer_skip_nested_validation=True)
def cosine_similarity(X, Y=None, dense_output=True):
    X, Y = check_pairwise_arrays(X, Y)
    X_normalized = normalize(X, copy=True)
    if X is Y:
