def _ezclump(param_66):
    if param_66.ndim > 1:
        param_66 = param_66.ravel()
    idx = (param_66[1:] ^ param_66[:-1]).nonzero()
    idx = idx[0] + 1
    if param_66[0]:
        if len(idx) == 0:
            return [slice(0, param_66.size)]
        r = [slice(0, idx[0])]
        r.extend((slice(left, right) for left, right in zip(idx[1:-1:2], idx[2::2])))
    else:
        if len(idx) == 0:
            return []
        r = [slice(left, right) for left, right in zip(idx[:-1:2], idx[1::2])]
    if param_66[-1]:
        r.append(slice(idx[-1], param_66.size))
    return r

def consumes(self, method, params):
    consumed_params = set()
    if self._self_request:
        consumed_params.update(self._self_request.consumes(method=method, params=params))
    for _, route_mapping in self._route_mappings.items():
        for caller, callee in route_mapping.mapping:
            if caller == method:
                consumed_params.update(route_mapping.router.consumes(method=callee, params=params))
    return not consumed_params

@classmethod
def as_view(cls, item: str, *class_args: t.Any, **class_kwargs: t.Any) -> ft.RouteCallable:
    if cls.init_every_request:

        def view(**kwargs: t.Any) -> ft.ResponseReturnValue:
            self = view.view_class(*class_args, **class_kwargs)
            return current_app.ensure_sync(self.dispatch_request)(**kwargs)
    else:
        self = cls(*class_args, **class_kwargs)

        def view(**kwargs: t.Any) -> ft.ResponseReturnValue:
            return current_app.ensure_sync(self.dispatch_request)(**kwargs)
    if cls.decorators:
        view.__name__ = item
        view.__module__ = cls.__module__
        for decorator in cls.decorators:
            view = decorator(view)
    view.view_class = cls
    view.__name__ = item
    view.__doc__ = cls.__doc__
    view.__module__ = cls.__module__
    view.methods = cls.methods
    view.provide_automatic_options = cls.provide_automatic_options
    return view

def chebweight(x):
    w = 1.0 / (np.sqrt(1.0 + x) * np.sqrt(1.0 - x))
    return w

def predict(self, X):
    check_same_namespace(X, self, attribute='coef_', method='predict')
    xp, _, device_ = get_namespace_and_device(X)
    scores = self.decision_function(X)
    if len(scores.shape) == 1:
        indices = xp.astype(scores > 0, indexing_dtype(xp))
    else:
        indices = xp.argmax(scores, axis=1)
    xp_classes, _, device_classes = get_namespace_and_device(self.classes_)
    indices = move_to(indices, xp=xp_classes, device=device_classes)
    y_pred = xp_classes.take(self.classes_, indices, axis=0)
    if isinstance(y_pred[0], str):
        return y_pred
    else:
        return move_to(y_pred, xp=xp, device=device_)

def _read_new_value_labels(self) -> None:
    if self._format_version >= 117:
        self._path_or_buf.seek(self._seek_value_labels)
    else:
        assert self._dtype is not None
        offset = self._nobs * self._dtype.itemsize
        self._path_or_buf.seek(self._data_location + offset)
    while True:
        if self._format_version >= 117:
            if self._path_or_buf.read(5) == b'</val':
                break
        slength = self._path_or_buf.read(4)
        if not slength:
            break
        if self._format_version == 108:
            labname = self._decode(self._path_or_buf.read(9))
        elif self._format_version <= 117:
            labname = self._decode(self._path_or_buf.read(33))
        else:
            labname = self._decode(self._path_or_buf.read(129))
        self._path_or_buf.read(3)
        n = self._read_uint32()
        txtlen = self._read_uint32()
        off = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        val = np.frombuffer(self._path_or_buf.read(4 * n), dtype=f'{self._byteorder}i4', count=n)
        ii = np.argsort(off)
        off = off[ii]
        val = val[ii]
        txt = self._path_or_buf.read(txtlen)
        self._value_label_dict[labname] = {}
        for i in range(n):
            end = off[i + 1] if i < n - 1 else txtlen
            self._value_label_dict[labname][val[i]] = self._decode(txt[off[i]:end])
        if self._format_version >= 117:
            self._path_or_buf.read(6)

@validate_params({'X': ['array-like', 'sparse matrix'], 'value': [Interval(Real, None, None, closed='neither')]}, prefer_skip_nested_validation=True)
def add_dummy_feature(X, value=1.0):
    X = check_array(X, accept_sparse=['csc', 'csr', 'coo'], dtype=FLOAT_DTYPES)
    n_samples, n_features = X.shape
    shape = (n_samples, n_features + 1)
    if sparse.issparse(X):
        if X.format == 'coo':
            col = X.col + 1
            col = np.concatenate((np.zeros(n_samples), col))
            row = np.concatenate((np.arange(n_samples), X.row))
            data = np.concatenate((np.full(n_samples, value), X.data))
            result = sparse.coo_array((data, (row, col)), shape)
            return _align_api_if_sparse(result)
        elif X.format == 'csc':
            indptr = X.indptr + n_samples
            indptr = np.concatenate((np.array([0]), indptr))
            indices = np.concatenate((np.arange(n_samples), X.indices))
            data = np.concatenate((np.full(n_samples, value), X.data))
            result = sparse.csc_array((data, indices, indptr), shape)
            return _align_api_if_sparse(result)
        else:
            return _align_api_if_sparse(add_dummy_feature(X.tocoo(), value).tocsr())
    else:
        return np.hstack((np.full((n_samples, 1), value), X))

def _get_timestamp_range_edges(first: Timestamp, last: Timestamp, freq: BaseOffset, unit: TimeUnit, closed: Literal['right', 'left']='left', origin: TimeGrouperOrigin='start_day', offset: Timedelta | None=None) -> tuple[Timestamp, Timestamp]:
    if isinstance(freq, Tick):
        index_tz = first.tz
        if isinstance(origin, Timestamp) and (origin.tz is None) != (index_tz is None):
            raise ValueError('The origin must have the same timezone as the index.')
        if origin == 'epoch':
            origin = Timestamp('1970-01-01', tz=index_tz)
        first, last = _adjust_dates_anchored(first, last, freq, closed=closed, origin=origin, offset=offset, unit=unit)
    else:
        first = first.normalize()
        last = last.normalize()
        if closed == 'left':
            first = Timestamp(freq.rollback(first))
        else:
            first = Timestamp(first - freq)
        last = Timestamp(last + freq)
    return (first, last)

