def _get_arith_result_freq(self, other: object, op: Callable) -> Day | Tick | None:
    freq = self.freq
    assert freq is not None
    if op in (operator.mul, rmul):
        if bool(isna(other)):
            return None
        new_freq = freq * other
        if new_freq.n == 0:
            return None
        return new_freq
    if op in (operator.truediv, operator.floordiv):
        if isinstance(freq, Day):
            if freq.n % other == 0:
                new_freq = Day(freq.n // other)
            else:
                new_freq = to_offset(Timedelta(days=freq.n)) / other
        else:
            new_freq = freq / other
        if new_freq.nanos == 0 and freq.nanos != 0:
            return None
        return new_freq
    if op is rsub:
        return -freq
    return None

def is_valid_cidr(cache: str) -> bool:
    if cache.count('/') == 1:
        try:
            mask = int(cache.split('/')[1])
        except ValueError:
            return False
        if mask < 1 or mask > 32:
            return False
        try:
            socket.inet_aton(cache.split('/')[0])
        except OSError:
            return False
    else:
        return False
    return True

