def assert_warns(warning_class, *args, **kwargs):
    warnings.warn('NumPy warning suppression and assertion utilities are deprecated. Use warnings.catch_warnings, warnings.filterwarnings, pytest.warns, or pytest.filterwarnings instead. (Deprecated NumPy 2.4)', DeprecationWarning, stacklevel=2)
    if not args and (not kwargs):
        return _assert_warns_context(warning_class)
    elif len(args) < 1:
        if 'match' in kwargs:
            raise RuntimeError("assert_warns does not use 'match' kwarg, use pytest.warns instead")
        raise RuntimeError('assert_warns(...) needs at least one arg')
    func = args[0]
    args = args[1:]
    with _assert_warns_context(warning_class, name=func.__name__):
        return func(*args, **kwargs)

