@set_module('numpy.char')
def array(obj, itemsize=None, copy=True, unicode=None, order=None):
    if isinstance(obj, (bytes, str)):
        if unicode is None:
            if isinstance(obj, str):
                unicode = True
            else:
                unicode = False
        if itemsize is None:
            itemsize = len(obj)
        shape = len(obj) // itemsize
        return chararray(shape, itemsize=itemsize, unicode=unicode, buffer=obj, order=order)
    if isinstance(obj, (list, tuple)):
        obj = asnarray(obj)
    if isinstance(obj, ndarray) and issubclass(obj.dtype.type, character):
        if not isinstance(obj, chararray):
            obj = obj.view(chararray)
        if itemsize is None:
            itemsize = obj.itemsize
            if issubclass(obj.dtype.type, str_):
                itemsize //= 4
        if unicode is None:
            if issubclass(obj.dtype.type, str_):
                unicode = True
            else:
                unicode = False
        if unicode:
            dtype = str_
        else:
            dtype = bytes_
        if order is not None:
            obj = asnarray(obj, order=order)
        if copy or itemsize != obj.itemsize or (not unicode and isinstance(obj, str_)) or (unicode and isinstance(obj, bytes_)):
            obj = obj.astype((dtype, int(itemsize)))
        return obj
    if isinstance(obj, ndarray) and issubclass(obj.dtype.type, object):
        if itemsize is None:
            obj = obj.tolist()
    if unicode:
        dtype = str_
    else:
        dtype = bytes_
    if itemsize is None:
        val = narray(obj, dtype=dtype, order=order, subok=True)
    else:
        val = narray(obj, dtype=(dtype, itemsize), order=order, subok=True)
    return val.view(chararray)

def predict_log_proba(self, X):
