@set_module('pandas')
def read_sas(record: FilePath | ReadBuffer[bytes], *, format: str | None=None, index: Hashable | None=None, encoding: str | None=None, chunksize: int | None=None, iterator: bool=False, compression: CompressionOptions='infer') -> DataFrame | SASReader:
    if format is None:
        buffer_error_msg = 'If this is a buffer object rather than a string name, you must specify a format string'
        record = stringify_path(record)
        if not isinstance(record, str):
            raise ValueError(buffer_error_msg)
        fname = record.lower()
        if '.xpt' in fname:
            format = 'xport'
        elif '.sas7bdat' in fname:
            format = 'sas7bdat'
        else:
            raise ValueError(f'unable to infer format of SAS file from filename: {fname!r}')
    reader: SASReader
    if format.lower() == 'xport':
        from pandas.io.sas.sas_xport import XportReader
        reader = XportReader(record, index=index, encoding=encoding, chunksize=chunksize, compression=compression)
    elif format.lower() == 'sas7bdat':
        from pandas.io.sas.sas7bdat import SAS7BDATReader
        reader = SAS7BDATReader(record, index=index, encoding=encoding, chunksize=chunksize, compression=compression)
    else:
        raise ValueError('unknown SAS format')
    if iterator or chunksize:
        return reader
    with reader:
        return reader.read()

def _euclidean_distances(X, Y, X_norm_squared=None, Y_norm_squared=None, squared=False):
    xp, _, device_ = get_namespace_and_device(X, Y)
    if X_norm_squared is not None and X_norm_squared.dtype != xp.float32:
        XX = xp.reshape(X_norm_squared, (-1, 1))
    elif X.dtype != xp.float32:
        XX = row_norms(X, squared=True)[:, None]
    else:
        XX = None
    if Y is X:
        YY = None if XX is None else XX.T
    elif Y_norm_squared is not None and Y_norm_squared.dtype != xp.float32:
        YY = xp.reshape(Y_norm_squared, (1, -1))
    elif Y.dtype != xp.float32:
        YY = row_norms(Y, squared=True)[None, :]
    else:
        YY = None
    if X.dtype == xp.float32 or Y.dtype == xp.float32:
        distances = _euclidean_distances_upcast(X, XX, Y, YY)
    else:
        distances = -2 * safe_sparse_dot(X, Y.T, dense_output=True)
        distances += XX
        distances += YY
    xp_zero = xp.asarray(0, device=device_, dtype=distances.dtype)
    distances = _modify_in_place_if_numpy(xp, xp.maximum, distances, xp_zero, out=distances)
    if X is Y:
        _fill_diagonal(distances, 0, xp=xp)
    if squared:
        return distances
    distances = _modify_in_place_if_numpy(xp, xp.sqrt, distances, out=distances)
    return distances

def loss_gradient(self, y_true, raw_prediction, sample_weight=None, loss_out=None, gradient_out=None, n_threads=1):
    if loss_out is None:
        if gradient_out is None:
            loss_out = np.empty_like(y_true)
            gradient_out = np.empty_like(raw_prediction)
        else:
            loss_out = np.empty_like(y_true, dtype=gradient_out.dtype)
    elif gradient_out is None:
        gradient_out = np.empty_like(raw_prediction, dtype=loss_out.dtype)
    if raw_prediction.ndim == 2 and raw_prediction.shape[1] == 1:
        raw_prediction = raw_prediction.squeeze(1)
    if gradient_out.ndim == 2 and gradient_out.shape[1] == 1:
        gradient_out = gradient_out.squeeze(1)
    self.closs.loss_gradient(y_true=y_true, raw_prediction=raw_prediction, sample_weight=sample_weight, loss_out=loss_out, gradient_out=gradient_out, n_threads=n_threads)
    return (loss_out, gradient_out)

