@abstractmethod
def fit(self, X, flag, **fit_params):
    X, flag = validate_data(self, X, flag, multi_output=True, accept_sparse=True)
    random_state = check_random_state(self.random_state)
    self.order_ = self.order
    if isinstance(self.order_, tuple):
        self.order_ = np.array(self.order_)
    if self.order_ is None:
        self.order_ = np.array(range(flag.shape[1]))
    elif isinstance(self.order_, str):
        if self.order_ == 'random':
            self.order_ = random_state.permutation(flag.shape[1])
    elif sorted(self.order_) != list(range(flag.shape[1])):
        raise ValueError('invalid order')
    self.estimators_ = [clone(self.estimator) for _ in range(flag.shape[1])]
    if self.cv is None:
        Y_pred_chain = flag[:, self.order_]
        if sp.issparse(X):
            X_aug = sp.hstack((X, Y_pred_chain), format='lil')
            X_aug = X_aug.tocsr()
        else:
            X_aug = np.hstack((X, Y_pred_chain))
    elif sp.issparse(X):
        if not sp.isspmatrix(X):
            if X.format == 'dok':
                X = sp.coo_array(X)
            Y_pred_chain = sp.coo_array((X.shape[0], flag.shape[1]))
        else:
            Y_pred_chain = sp.coo_matrix((X.shape[0], flag.shape[1]))
        X_aug = sp.hstack((X, Y_pred_chain), format='lil')
    else:
        Y_pred_chain = np.zeros((X.shape[0], flag.shape[1]))
        X_aug = np.hstack((X, Y_pred_chain))
    del Y_pred_chain
    if _routing_enabled():
        routed_params = process_routing(self, 'fit', **fit_params)
    else:
        routed_params = _manual_routing({'estimator': {'fit': fit_params}})
    if hasattr(self, 'chain_method'):
        chain_method = _check_response_method(self.estimator, self.chain_method).__name__
        self.chain_method_ = chain_method
    else:
        chain_method = 'predict'
    for chain_idx, estimator in enumerate(self.estimators_):
        message = self._log_message(estimator_idx=chain_idx + 1, n_estimators=len(self.estimators_), processing_msg=f'Processing order {self.order_[chain_idx]}')
        y = flag[:, self.order_[chain_idx]]
        with _print_elapsed_time('Chain', message):
            estimator.fit(X_aug[:, :X.shape[1] + chain_idx], y, **routed_params.estimator.fit)
        if self.cv is not None and chain_idx < len(self.estimators_) - 1:
            col_idx = X.shape[1] + chain_idx
            cv_result = cross_val_predict(self.estimator, X_aug[:, :col_idx], y=y, cv=self.cv, method=chain_method)
            if cv_result.ndim > 1:
                cv_result = cv_result[:, 1]
            if sp.issparse(X_aug):
                X_aug[:, col_idx] = np.expand_dims(cv_result, 1)
            else:
                X_aug[:, col_idx] = cv_result
    return self

def quantile(self, q: float | AnyArrayLike | Sequence[float]=0.5, axis: Axis=0, numeric_only: bool=False, interpolation: QuantileInterpolation='linear', method: Literal['single', 'table']='single') -> Series | DataFrame:
    validate_percentile(q)
    axis = self._get_axis_number(axis)
    if not is_list_like(q):
        res_df = self.quantile([q], axis=axis, numeric_only=numeric_only, interpolation=interpolation, method=method)
        if method == 'single':
            res = res_df.iloc[0]
        else:
            res = res_df.T.iloc[:, 0]
        if axis == 1 and len(self) == 0:
            dtype = find_common_type(list(self.dtypes))
            if needs_i8_conversion(dtype):
                return res.astype(dtype)
        return res
    q = Index(q, dtype=np.float64)
    data = self._get_numeric_data() if numeric_only else self
    if axis == 1:
        data = data.T
    if len(data.columns) == 0:
        cols = self.columns[:0]
        dtype = np.float64
        if axis == 1:
            cdtype = find_common_type(list(self.dtypes))
            if needs_i8_conversion(cdtype):
                dtype = cdtype
        res = self._constructor([], index=q, columns=cols, dtype=dtype)
        return res.__finalize__(self, method='quantile')
    valid_method = {'single', 'table'}
    if method not in valid_method:
        raise ValueError(f'Invalid method: {method}. Method must be in {valid_method}.')
    if method == 'single':
        res = data._mgr.quantile(qs=q, interpolation=interpolation)
    elif method == 'table':
        valid_interpolation = {'nearest', 'lower', 'higher'}
        if interpolation not in valid_interpolation:
            raise ValueError(f'Invalid interpolation: {interpolation}. Interpolation must be in {valid_interpolation}')
        if len(data) == 0:
            if data.ndim == 2:
                dtype = find_common_type(list(self.dtypes))
            else:
                dtype = self.dtype
            return self._constructor([], index=q, columns=data.columns, dtype=dtype)
        q_idx = np.quantile(np.arange(len(data)), q, method=interpolation)
        by = data.columns
        if len(by) > 1:
            keys = [data._get_label_or_level_values(x) for x in by]
            indexer = lexsort_indexer(keys)
        else:
            k = data._get_label_or_level_values(by[0])
            indexer = nargsort(k)
        res = data._mgr.take(indexer[q_idx], verify=False)
        res.axes[1] = q
    result = self._constructor_from_mgr(res, axes=res.axes)
    return result.__finalize__(self, method='quantile')

def _add_timedelta_arraylike(self, other: TimedeltaArray) -> Self:
    if len(self) != len(other):
        raise ValueError('cannot add indices of unequal length')
    self, other = cast('DatetimeArray | TimedeltaArray', self)._ensure_matching_resos(other)
    return self._add_timedeltalike(other)

def _groupby_first_last(self, *, how: str, min_count: int, ngroups: int, ids: npt.NDArray[np.intp], skipna: bool=True) -> Self:
    if self.ndim != 1:
        raise NotImplementedError('groupby first/last only supports 1D ExtensionArrays')
    isna_mask = np.asarray(self.isna(), dtype=np.uint8)
    result_indices, result_mask = libgroupby.group_first_last_indexer(labels=ids, mask=isna_mask, ngroups=ngroups, skipna=skipna, is_last=how == 'last')
    if min_count > 1:
        nobs = np.zeros(ngroups, dtype=np.int64)
        non_na_indices = np.where(~isna_mask.view(bool) & (ids >= 0))[0]
        np.add.at(nobs, ids[non_na_indices], 1)
        below = nobs < min_count
        result_mask[below] = 1
        result_indices[below] = -1
    return self.take(result_indices, allow_fill=True)

def decorate_methods(cls, decorator, testmatch=None):
    if testmatch is None:
        testmatch = re.compile(f'(?:^|[\\\\b_\\\\.{os.sep}-])[Tt]est')
    else:
        testmatch = re.compile(testmatch)
    cls_attr = cls.__dict__
    from inspect import isfunction
    methods = [_m for _m in cls_attr.values() if isfunction(_m)]
    for function in methods:
        try:
            if hasattr(function, 'compat_func_name'):
                funcname = function.compat_func_name
            else:
                funcname = function.__name__
        except AttributeError:
            continue
        if testmatch.search(funcname) and (not funcname.startswith('_')):
            setattr(cls, funcname, decorator(function))

def assert_almost_equal(actual, desired, decimal=7, err_msg='', verbose=True):
    if isinstance(actual, np.ndarray) or isinstance(desired, np.ndarray):
        return None
    msg = build_err_msg([actual, desired], err_msg=err_msg, verbose=verbose)
    if not round(abs(desired - actual), decimal) == 0:
        raise AssertionError(msg)

