@array_function_dispatch(_drop_fields_dispatcher)
def drop_fields(base, drop_names, usemask=True, asrecarray=False):
    if _is_string_like(drop_names):
        drop_names = [drop_names]
    else:
        drop_names = set(drop_names)

    def _drop_descr(ndtype, drop_names):
        names = ndtype.names
        newdtype = []
        for name in names:
            current = ndtype[name]
            if name in drop_names:
                continue
            if current.names is not None:
                descr = _drop_descr(current, drop_names)
                if descr:
                    newdtype.append((name, descr))
            else:
                newdtype.append((name, current))
        return newdtype
    newdtype = _drop_descr(base.dtype, drop_names)
    output = np.empty(base.shape, dtype=newdtype)
    output = recursive_fill_fields(base, output)
    return _fix_output(output, usemask=usemask, asrecarray=asrecarray)

def _get_cell_string_value(self, cell) -> str:
    from odf.element import Element
    from odf.namespaces import TEXTNS
    from odf.office import Annotation
    from odf.text import S
    office_annotation = Annotation().qname
    text_s = S().qname
    value = []
    for fragment in cell.childNodes:
        if isinstance(fragment, Element):
            if fragment.qname == text_s:
                spaces = int(fragment.attributes.get((TEXTNS, 'c'), 1))
                value.append(' ' * spaces)
            elif fragment.qname == office_annotation:
                continue
            else:
                value.append(self._get_cell_string_value(fragment))
        else:
            value.append(str(fragment).strip('\n'))
    return ''.join(value)

@classmethod
def _convert_to_fill(cls, handle: dict[str, Any]) -> Fill:
    from openpyxl.styles import GradientFill, PatternFill
    _pattern_fill_key_map = {'patternType': 'fill_type', 'patterntype': 'fill_type', 'fgColor': 'start_color', 'fgcolor': 'start_color', 'bgColor': 'end_color', 'bgcolor': 'end_color'}
    _gradient_fill_key_map = {'fill_type': 'type'}
    pfill_kwargs = {}
    gfill_kwargs = {}
    for k, v in handle.items():
        pk = _pattern_fill_key_map.get(k)
        gk = _gradient_fill_key_map.get(k)
        if pk in ['start_color', 'end_color']:
            v = cls._convert_to_color(v)
        if gk == 'stop':
            v = cls._convert_to_stop(v)
        if pk:
            pfill_kwargs[pk] = v
        elif gk:
            gfill_kwargs[gk] = v
        else:
            pfill_kwargs[k] = v
            gfill_kwargs[k] = v
    try:
        return PatternFill(**pfill_kwargs)
    except TypeError:
        return GradientFill(**gfill_kwargs)

def after_this_request(f: ft.AfterRequestCallable[t.Any]) -> ft.AfterRequestCallable[t.Any]:
    ctx = _cv_app.get(None)
    if ctx is None or not ctx.has_request:
        raise RuntimeError("'after_this_request' can only be used when a request context is active, such as in a view function.")
    ctx._after_request_functions.append(f)
    return f

docstring:
Decorate a function to run after the current request. The behavior is the
same as :meth:`.Flask.after_request`, except it only applies to the current
request, rather than every request. Therefore, it must be used within a
request context, rather than during setup.

.. code-block:: python

    @app.route("/")
    def index():
        @after_this_request
        def add_header(response):
            response.headers["X-Foo"] = "Parachute"
            return response

        return "Hello, World!"

