def isin(self, item: ArrayLike) -> npt.NDArray[np.bool_]:
    if item.dtype.kind in 'fiuc':
        return np.zeros(self.shape, dtype=bool)
    item = ensure_wrapped_if_datetimelike(item)
    if not isinstance(item, type(self)):
        if item.dtype == object:
            item = lib.maybe_convert_objects(item, convert_non_numeric=True, dtype_if_all_nat=self.dtype)
            if item.dtype != object:
                return self.isin(item)
            else:
                return isin(self.astype(object), item)
        return np.zeros(self.shape, dtype=bool)
    if self.dtype.kind in 'mM':
        self = cast('DatetimeArray | TimedeltaArray', self)
        self, item = self._ensure_matching_resos(item)
    try:
        self._check_compatible_with(item)
    except (TypeError, ValueError):
        return np.zeros(self.shape, dtype=bool)
    return isin(self.asi8, item.asi8)

