@final
def interpolate(self, method: InterpolateOptions='linear', *, axis: Axis=0, limit: int | None=None, limit_direction: Literal['forward', 'backward', 'both']='forward', limit_area=None, **kwargs):
    if 'inplace' in kwargs:
        warnings.warn(f"The 'inplace' keyword in {type(self).__name__}.interpolate is deprecated and will be removed in a future version. resample(...).interpolate is never inplace.", Pandas4Warning, stacklevel=find_stack_level())
        inplace = kwargs.pop('inplace')
        if inplace:
            raise ValueError('Cannot interpolate inplace on a resampled object.')
    result = self._upsample('asfreq')
    obj = self._selected_obj
    is_period_index = isinstance(obj.index, PeriodIndex)
    if not is_period_index:
        final_index = result.index
        if isinstance(final_index, MultiIndex):
            raise NotImplementedError('Direct interpolation of MultiIndex data frames is not supported. If you tried to resample and interpolate on a grouped data frame, please use:\n`df.groupby(...).apply(lambda x: x.resample(...).interpolate(...))`\ninstead, as resampling and interpolation has to be performed for each group independently.')
        missing_data_points_index = obj.index.difference(final_index)
        if len(missing_data_points_index) > 0:
            result = concat([result, obj.loc[missing_data_points_index]]).sort_index()
    result_interpolated = result.interpolate(method=method, axis=axis, limit=limit, inplace=False, limit_direction=limit_direction, limit_area=limit_area, **kwargs)
    if is_period_index:
        return result_interpolated
    result_interpolated = result_interpolated.loc[final_index]
    result_interpolated.index = final_index
    return result_interpolated

