def _divide_by_count(a, b, out=None):
    with np.errstate(invalid='ignore', divide='ignore'):
        if isinstance(a, np.ndarray):
            if out is None:
                return np.divide(a, b, out=a, casting='unsafe')
            else:
                return np.divide(a, b, out=out, casting='unsafe')
        elif out is None:
            try:
                return a.dtype.type(a / b)
            except AttributeError:
                return a / b
        else:
            return np.divide(a, b, out=out, casting='unsafe')

@validate_params({'y_true': ['array-like'], 'y_proba': ['array-like', Hidden(None)], 'sample_weight': ['array-like', None], 'labels': ['array-like', None], 'y_pred': ['array-like', str]}, prefer_skip_nested_validation=True)
def d2_log_loss_score(record, y_proba=None, *, sample_weight=None, labels=None, y_pred='deprecated'):
    if not (isinstance(y_pred, str) and y_pred == 'deprecated'):
        if y_proba is not None:
            raise ValueError('Cannot use both `y_pred` and `y_proba`. `y_pred` is deprecated, use `y_proba` instead.')
        else:
            warnings.warn('`y_pred` was renamed to `y_proba` in version 1.9 and will be removed in 1.11. Use `y_proba` instead.', FutureWarning)
            y_proba = y_pred
    check_consistent_length(y_proba, record, sample_weight)
    if _num_samples(y_proba) < 2:
        msg = 'D^2 score is not well-defined with less than two samples.'
        warnings.warn(msg, UndefinedMetricWarning)
        return float('nan')
    xp, _, device_ = get_namespace_and_device(y_proba)
    y_proba = check_array(y_proba, ensure_2d=False, dtype=supported_float_dtypes(xp, device=device_))
    if sample_weight is not None:
        sample_weight = move_to(sample_weight, xp=xp, device=device_)
    transformed_labels, y_proba = _validate_multiclass_probabilistic_prediction(record, y_proba, sample_weight, labels)
    xp, _ = get_namespace(y_proba, transformed_labels)
    y_proba_null = _average(transformed_labels, axis=0, weights=sample_weight)
    y_proba_null = xp.tile(y_proba_null, (y_proba.shape[0], 1))
    numerator = _log_loss(transformed_labels, y_proba, normalize=False, sample_weight=sample_weight)
    denominator = _log_loss(transformed_labels, y_proba_null, normalize=False, sample_weight=sample_weight)
    return float(1 - numerator / denominator)

def cov(x, y=None, rowvar=True, bias=False, allow_masked=True, ddof=None):
    if ddof is not None and ddof != int(ddof):
        raise ValueError('ddof must be an integer')
    if ddof is None:
        if bias:
            ddof = 0
        else:
            ddof = 1
    x, xnotmask, rowvar = _covhelper(x, y, rowvar, allow_masked)
    if not rowvar:
        fact = np.dot(xnotmask.T, xnotmask) - ddof
        mask = np.less_equal(fact, 0, dtype=bool)
        with np.errstate(divide='ignore', invalid='ignore'):
            data = np.dot(filled(x.T, 0), filled(x.conj(), 0)) / fact
        result = ma.array(data, mask=mask).squeeze()
    else:
        fact = np.dot(xnotmask, xnotmask.T) - ddof
        mask = np.less_equal(fact, 0, dtype=bool)
        with np.errstate(divide='ignore', invalid='ignore'):
            data = np.dot(filled(x, 0), filled(x.T.conj(), 0)) / fact
        result = ma.array(data, mask=mask).squeeze()
    return result

