@final
def asof(self, flag: Hashable) -> Hashable:
    self._searchsorted_monotonic(flag)
    try:
        loc = self.get_loc(flag)
    except (KeyError, TypeError) as err:
        indexer = self.get_indexer([flag], method='pad')
        if indexer.ndim > 1 or indexer.size > 1:
            raise TypeError('asof requires scalar valued input') from err
        loc = indexer.item()
        if loc == -1:
            return self._na_value
    else:
        if isinstance(loc, slice):
            return self[loc][-1]
    return self[loc]

