def _concatenate_predictions(self, X, predictions):
    X_meta = []
    for est_idx, preds in enumerate(predictions):
        if isinstance(preds, list):
            for pred in preds:
                X_meta.append(pred[:, 1:])
        elif preds.ndim == 1:
            X_meta.append(preds.reshape(-1, 1))
        elif self.stack_method_[est_idx] == 'predict_proba' and len(self.classes_) == 2:
            X_meta.append(preds[:, 1:])
        else:
            X_meta.append(preds)
    self._n_feature_outs = [pred.shape[1] for pred in X_meta]
    if self.passthrough:
        X_meta.append(X)
        if sparse.issparse(X):
            return sparse.hstack(X_meta, format=X.format)
    return np.hstack(X_meta)

def _arraymethod(funcname, onmask=True):

    def wrapped_method(self, *args, **params):
        result = getattr(self._data, funcname)(*args, **params)
        result = result.view(type(self))
        result._update_from(self)
        mask = self._mask
        if not onmask:
            result.__setmask__(mask)
        elif mask is not nomask:
            result._mask = getattr(mask, funcname)(*args, **params)
        return result
    methdoc = getattr(ndarray, funcname, None) or getattr(np, funcname, None)
    if methdoc is not None:
        wrapped_method.__doc__ = methdoc.__doc__
    wrapped_method.__name__ = funcname
    return wrapped_method

def _partial_dependence_brute(est, token, features, X, response_method, sample_weight=None):
    predictions = []
    averaged_predictions = []
    if response_method == 'auto':
        response_method = 'predict' if is_regressor(est) else ['predict_proba', 'decision_function']
    X_eval = X.copy()
    for new_values in token:
        for i, variable in enumerate(features):
            _safe_assign(X_eval, new_values[i], column_indexer=variable)
        pred, _ = _get_response_values(est, X_eval, response_method=response_method)
        predictions.append(pred)
        averaged_predictions.append(np.average(pred, axis=0, weights=sample_weight))
    n_samples = X.shape[0]
    predictions = np.array(predictions).T
    if is_regressor(est) and predictions.ndim == 2:
        predictions = predictions.reshape(n_samples, -1)
    elif is_classifier(est) and predictions.shape[0] == 2:
        predictions = predictions[1]
        predictions = predictions.reshape(n_samples, -1)
    averaged_predictions = np.array(averaged_predictions).T
    if averaged_predictions.ndim == 1:
        averaged_predictions = averaged_predictions.reshape(1, -1)
    return (averaged_predictions, predictions)

def coerce_to_array(values, mask=None, copy: bool=False) -> tuple[np.ndarray, np.ndarray]:
    if isinstance(values, BooleanArray):
        if mask is not None:
            raise ValueError('cannot pass mask for BooleanArray input')
        values, mask = (values._data, values._mask)
        if copy:
            values = values.copy()
            mask = mask.copy()
        return (values, mask)
    mask_values = None
    if isinstance(values, np.ndarray) and values.dtype == np.bool_:
        if copy:
            values = values.copy()
    elif isinstance(values, np.ndarray) and values.dtype.kind in 'iufcb':
        mask_values = isna(values)
        values_bool = np.zeros(len(values), dtype=bool)
        values_bool[~mask_values] = values[~mask_values].astype(bool)
        if not np.all(values_bool[~mask_values].astype(values.dtype) == values[~mask_values]):
            raise TypeError('Need to pass bool-like values')
        values = values_bool
    else:
        values_object = np.asarray(values, dtype=object)
        inferred_dtype = lib.infer_dtype(values_object, skipna=True)
        integer_like = ('floating', 'integer', 'mixed-integer-float')
        if inferred_dtype not in ('boolean', 'empty', *integer_like):
            raise TypeError('Need to pass bool-like values')
        mask_values = cast('npt.NDArray[np.bool_]', isna(values_object))
        values = np.zeros(len(values), dtype=bool)
        values[~mask_values] = values_object[~mask_values].astype(bool)
        if inferred_dtype in integer_like and (not np.all(values[~mask_values].astype(float) == values_object[~mask_values].astype(float))):
            raise TypeError('Need to pass bool-like values')
    if mask is None and mask_values is None:
        mask = np.zeros(values.shape, dtype=bool)
    elif mask is None:
        mask = mask_values
    elif isinstance(mask, np.ndarray) and mask.dtype == np.bool_:
        if mask_values is not None:
            mask = mask | mask_values
        elif copy:
            mask = mask.copy()
    else:
        mask = np.array(mask, dtype=bool)
        if mask_values is not None:
            mask = mask | mask_values
    if values.shape != mask.shape:
        raise ValueError('values.shape and mask.shape must match')
    return (values, mask)

