@array_function_dispatch(_trim_zeros)
def trim_zeros(filt, trim='fb', axis=None):
    filt_ = np.asarray(filt)
    trim = trim.lower()
    if trim not in {'fb', 'bf', 'f', 'b'}:
        raise ValueError(f'unexpected character(s) in `trim`: {trim!r}')
    if axis is None:
        axis_tuple = tuple(range(filt_.ndim))
    else:
        axis_tuple = _nx.normalize_axis_tuple(axis, filt_.ndim, argname='axis')
    if not axis_tuple:
        return filt
    start, stop = _arg_trim_zeros(filt_)
    stop += 1
    if start.size == 0:
        start = stop = np.zeros(filt_.ndim, dtype=np.intp)
    else:
        if 'f' not in trim:
            start = (None,) * filt_.ndim
        if 'b' not in trim:
            stop = (None,) * filt_.ndim
    sl = tuple((slice(start[ax], stop[ax]) if ax in axis_tuple else slice(None) for ax in range(filt_.ndim)))
    if len(sl) == 1:
        return filt[sl[0]]
    return filt[sl]

def _or_of_ands_columns(condition) -> set[str]:
    cols: set[str] = set()
    found = False

    def visit(node) -> None:
        nonlocal found
        if not isinstance(node, JointConditionBinOp):
            cols.add(node.lhs.value)
            return
        if node.op == '|' and (isinstance(node.lhs, JointConditionBinOp) and node.lhs.op == '&' or (isinstance(node.rhs, JointConditionBinOp) and node.rhs.op == '&')):
            found = True
        visit(node.lhs)
        visit(node.rhs)
    visit(condition)
    return cols if found else set()

def _assert_caught_no_extra_warnings(*, caught_warnings: Sequence[warnings.WarningMessage], expected_warning: type[Warning] | bool | tuple[type[Warning], ...] | None) -> None:
    extra_warnings = []
    for actual_warning in caught_warnings:
        if _is_unexpected_warning(actual_warning, expected_warning):
            if actual_warning.category == ResourceWarning:
                if 'unclosed <ssl.SSLSocket' in str(actual_warning.message):
                    continue
                if any(('matplotlib' in mod for mod in sys.modules)):
                    continue
            if actual_warning.category == EncodingWarning:
                continue
            extra_warnings.append((actual_warning.category.__name__, actual_warning.message, actual_warning.filename, actual_warning.lineno))
    if extra_warnings:
        raise AssertionError(f'Caused unexpected warning(s): {extra_warnings!r}')

