def _parse_eq_to_pure_multiplication(a_term, shape_a, b_term, shape_b, out):
    desired_a = ''
    desired_b = ''
    new_shape_a = []
    new_shape_b = []
    for ix in out:
        if ix in a_term:
            desired_a += ix
            new_shape_a.append(shape_a[a_term.index(ix)])
        else:
            new_shape_a.append(1)
        if ix in b_term:
            desired_b += ix
            new_shape_b.append(shape_b[b_term.index(ix)])
        else:
            new_shape_b.append(1)
    if desired_a != a_term:
        eq_a = f'{a_term}->{desired_a}'
    else:
        eq_a = None
    if desired_b != b_term:
        eq_b = f'{b_term}->{desired_b}'
    else:
        eq_b = None
    return (eq_a, eq_b, new_shape_a, new_shape_b, None, None, True)

def write_data(self, chunksize: int | None, dropna: bool=False) -> None:
    names = self.dtype.names
    nrows = self.nrows_expected
    masks = []
    if dropna:
        for a in self.values_axes:
            mask = isna(a.data).all(axis=0)
            if isinstance(mask, np.ndarray):
                masks.append(mask.astype('u1', copy=False))
    if masks:
        mask = masks[0]
        for m in masks[1:]:
            mask = mask & m
        mask = mask.ravel()
    else:
        mask = None
    indexes = [a.cvalues for a in self.index_axes]
    nindexes = len(indexes)
    assert nindexes == 1, nindexes
    values = [a.take_data() for a in self.values_axes]
    values = [v.transpose(np.roll(np.arange(v.ndim), v.ndim - 1)) for v in values]
    bvalues = []
    for i, v in enumerate(values):
        new_shape = (nrows, *self.dtype[names[nindexes + i]].shape)
        bvalues.append(v.reshape(new_shape))
    if chunksize is None:
        chunksize = 100000
    rows = np.empty(min(chunksize, nrows), dtype=self.dtype)
    chunks = nrows // chunksize + 1
    for i in range(chunks):
        start_i = i * chunksize
        end_i = min((i + 1) * chunksize, nrows)
        if start_i >= end_i:
            break
        self.write_data_chunk(rows, indexes=[a[start_i:end_i] for a in indexes], mask=mask[start_i:end_i] if mask is not None else None, values=[v[start_i:end_i] for v in bvalues])

