def _log_reg_scoring_path(X, y, train, test, *, classes, Cs, scoring, fit_intercept, max_iter, tol, class_weight, verbose, solver, penalty, dual, intercept_scaling, random_state, max_squared_sum, sample_weight, l1_ratio, score_params):
    X_train = X[train]
    X_test = X[test]
    y_train = y[train]
    y_test = y[test]
    sw_train, sw_test = (None, None)
    if sample_weight is not None:
        sample_weight = _check_sample_weight(sample_weight, X)
        sw_train = sample_weight[train]
        sw_test = sample_weight[test]
    coefs, Cs, n_iter = _logistic_regression_path(X_train, y_train, classes=classes, Cs=Cs, l1_ratio=l1_ratio, fit_intercept=fit_intercept, solver=solver, max_iter=max_iter, class_weight=class_weight, tol=tol, verbose=verbose, dual=dual, penalty=penalty, intercept_scaling=intercept_scaling, random_state=random_state, check_input=False, max_squared_sum=max_squared_sum, sample_weight=sw_train, callback_ctx=None, estimator=None)
    log_reg = LogisticRegression(solver=solver)
    log_reg.classes_ = classes
    scores = list()
    scoring = get_scorer(scoring)
    if scoring is None:

        def calc_score(log_reg):
            return log_reg.score(X_test, y_test, sample_weight=sw_test)
    else:
        is_binary = len(classes) <= 2
        score_params = score_params or {}
        score_params = _check_method_params(X=X, params=score_params, indices=test)
        if hasattr(scoring, '_score_func'):
            sig = inspect.signature(scoring._score_func).parameters
        else:
            sig = []
        if 'labels' in sig:
            pos_label_kwarg = {}
            if is_binary and 'pos_label' in sig:
                pos_label_kwarg['pos_label'] = classes[-1]
            scoring = make_scorer(scoring._score_func, greater_is_better=True if scoring._sign == 1 else False, response_method=scoring._response_method, labels=classes, **pos_label_kwarg, **getattr(scoring, '_kwargs', {}))

        def calc_score(log_reg):
            return scoring(log_reg, X_test, y_test, **score_params)
    for w, C in zip(coefs, Cs):
        log_reg.C = C
        if fit_intercept:
            log_reg.coef_ = w[..., :-1]
            log_reg.intercept_ = w[..., -1]
        else:
            log_reg.coef_ = w
            log_reg.intercept_ = 0.0
        scores.append(calc_score(log_reg))
    return (coefs, Cs, np.array(scores), n_iter)

