def fillna(self, value, limit: int | None=None, copy: bool=True) -> Self:
    mask = self._mask
    value_is_na = is_valid_na_for_dtype(value, self.dtype) and (not (lib.is_float(value) and (not is_nan_na())))
    if lib.is_scalar(value) and (not value_is_na):
        if not mask.any():
            return self.copy() if copy else self[:]
        try:
            casted = self._validate_setitem_value(value)
        except TypeError:
            pass
        else:
            if copy:
                new_data = self._data.copy()
                new_mask = mask.copy()
            else:
                if self._readonly:
                    raise ValueError('Cannot modify read-only array')
                new_data = self._data
                new_mask = mask
            if new_data.dtype.kind == 'b':
                libalgos.scalar_fillna_inplace(new_data.view('u1'), np.uint8(casted), mask=new_mask.view('u1'), limit=limit)
            else:
                libalgos.scalar_fillna_inplace(new_data, casted, mask=new_mask.view('u1'), limit=limit)
            return type(self)(new_data, new_mask, copy=False)
    if limit is not None and limit < len(self):
        modify = mask.cumsum() > limit
        if modify.any():
            mask = mask.copy()
            mask[modify] = False
    value = missing.check_value_size(value, mask, len(self))
    if mask.any():
        if copy:
            new_values = self.copy()
        else:
            new_values = self[:]
        new_values[mask] = value
    elif copy:
        new_values = self.copy()
    else:
        new_values = self[:]
    return new_values

@final
def asof(self, where, subset=None):
    if isinstance(where, str):
        where = Timestamp(where)
    if not self.index.is_monotonic_increasing:
        raise ValueError('asof requires a sorted index')
    is_series = isinstance(self, ABCSeries)
    if is_series:
        if subset is not None:
            raise ValueError('subset is not valid for Series')
    else:
        if subset is None:
            subset = self.columns
        if not is_list_like(subset):
            subset = [subset]
    is_list = is_list_like(where)
    if not is_list:
        start = self.index[0]
        if isinstance(self.index, PeriodIndex):
            where = Period(where, freq=self.index.freq)
        if where < start:
            if not is_series:
                return self._constructor_sliced(index=self.columns, name=where, dtype=np.float64)
            return np.nan
        if is_series:
            loc = self.index.searchsorted(where, side='right')
            if loc > 0:
                loc -= 1
            values = self._values
            while loc > 0 and isna(values[loc]):
                loc -= 1
            return values[loc]
    if not isinstance(where, Index):
        where = Index(where) if is_list else Index([where])
    nulls = self.isna() if is_series else self[subset].isna().any(axis=1)
    if nulls.all():
        if is_series:
            self = cast('Series', self)
            return self._constructor(np.nan, index=where, name=self.name)
        elif is_list:
            self = cast('DataFrame', self)
            return self._constructor(np.nan, index=where, columns=self.columns)
        else:
            self = cast('DataFrame', self)
            return self._constructor_sliced(np.nan, index=self.columns, name=where[0])
    locs = self.index.asof_locs(where, ~nulls._values)
    mask = locs == -1
    data = self.take(locs)
    data.index = where
    if mask.any():
        data.loc[mask] = np.nan
    return data if is_list else data.iloc[-1]

