    if asof:
        raise NotImplementedError("'asof' argument is not supported")
    if isinstance(time, str):
        from dateutil.parser import parse
        orig = time
        try:
            alt = to_time(time)
        except ValueError:
            warnings.warn(f"The string '{orig}' cannot be parsed using pd.core.tools.to_time and in a future version will raise. Use an unambiguous time string format or explicitly cast to `datetime.time` before calling.", Pandas4Warning, stacklevel=find_stack_level())
            time = parse(time).time()
        else:
            try:
                time = parse(time).time()
            except ValueError:
                time = alt
            if alt != time:
                warnings.warn(f"The string '{orig}' is currently parsed as {time} but in a future version will be parsed as {alt}, consistentwith `between_time` behavior. To avoid this warning, use an unambiguous string format or explicitly cast to `datetime.time` before calling.", Pandas4Warning, stacklevel=find_stack_level())
    if time.tzinfo:
        if self.tz is None:
            raise ValueError('Index must be timezone aware.')
        time_micros = self.tz_convert(time.tzinfo)._get_time_micros()
    else:
        time_micros = self._get_time_micros()
    micros = _time_to_micros(time)
    return (time_micros == micros).nonzero()[0]

